@layer base {
  * {
    @apply border-border outline-ring/50;
    box-sizing: border-box;
  }
  body {
    @apply bg-background text-foreground;
    font-family: 'Outfit Variable', 'Outfit', sans-serif;
    overflow-x: hidden;
  }

  html[dir='rtl'] body {
    direction: rtl;
  }

  button:not(:disabled):not([aria-disabled="true"]),
  [role="button"]:not([aria-disabled="true"]),
  a[href]:not([aria-disabled="true"]),
  summary:not([aria-disabled="true"]),
  [role="tab"]:not([aria-disabled="true"]),
  [role="menuitem"]:not([aria-disabled="true"]),
  [role="menuitemcheckbox"]:not([aria-disabled="true"]),
  [role="menuitemradio"]:not([aria-disabled="true"]),
  [role="option"]:not([aria-disabled="true"]),
  [role="switch"]:not([data-disabled]),
  [role="combobox"]:not([aria-disabled="true"]) {
    cursor: pointer;
  }
}

@layer utilities {
  .wms-ltr,
  .font-mono,
  .tabular-nums,
  [data-wms-ltr='true'] {
    direction: ltr;
    unicode-bidi: isolate;
  }

  .wms-text-start {
    text-align: start;
  }

  .wms-text-end {
    text-align: end;
  }

  .wms-ms-auto {
    margin-inline-start: auto;
  }

  .wms-me-auto {
    margin-inline-end: auto;
  }

  html[dir='rtl'] .app-sidebar-panel {
    left: auto;
    right: 0;
    border-right-width: 0;
    border-left-width: 1px;
    box-shadow: -1px 0 0 rgba(15, 23, 42, 0.04);
  }

  html.dark[dir='rtl'] .app-sidebar-panel {
    box-shadow: -1px 0 0 rgba(255, 255, 255, 0.04);
  }

  html[dir='rtl'] .app-sidebar-panel[data-sidebar-open='false'] {
    --tw-translate-x: 100%;
    translate: var(--tw-translate-x) var(--tw-translate-y, 0);
  }

  @media (min-width: 64rem) {
    html[dir='rtl'] .app-sidebar-panel[data-sidebar-open='false'] {
      --tw-translate-x: 0;
      translate: var(--tw-translate-x) var(--tw-translate-y, 0);
    }

    html[dir='rtl'] .app-main-panel {
      margin-left: 0;
    }

    html[dir='rtl'] .app-sidebar-panel[data-sidebar-open='true'] + .app-main-panel {
      margin-right: 18rem;
    }

    html[dir='rtl'] .app-sidebar-panel[data-sidebar-open='false'] + .app-main-panel {
      margin-right: 5rem;
    }
  }

  html[dir='rtl'] [data-slot='table-head'],
  html[dir='rtl'] [data-slot='table-cell'] {
    text-align: start;
  }

  html[dir='rtl'] .management-data-grid th,
  html[dir='rtl'] .management-data-grid td,
  html[dir='rtl'] .wms-ops-data-grid th,
  html[dir='rtl'] .wms-ops-data-grid td {
    border-right-width: 0;
    border-left-width: 1px;
  }

  html[dir='rtl'] .management-data-grid th:last-child,
  html[dir='rtl'] .management-data-grid td:last-child,
  html[dir='rtl'] .wms-ops-data-grid th:last-child,
