  .custom-scrollbar::-webkit-scrollbar-track {
    background: transparent;
  }

  .custom-scrollbar::-webkit-scrollbar-thumb {
    background-color: oklch(0.704 0.04 256.788 / 0.3);
    border-radius: 10px;
    transition: background-color 0.2s ease;
