  }

  .dark .custom-scrollbar::-webkit-scrollbar-thumb:hover {
    background-color: oklch(0.551 0.027 264.364 / 0.5);
  }

  .custom-scrollbar-lg {
    scrollbar-width: auto;
    scrollbar-color: oklch(0.704 0.04 256.788 / 0.3) transparent;
  }

  .custom-scrollbar-lg::-webkit-scrollbar {
    width: 10px;
  }

  .custom-scrollbar-lg::-webkit-scrollbar-track {
    background: transparent;
  }

  .custom-scrollbar-lg::-webkit-scrollbar-thumb {
    background-color: oklch(0.704 0.04 256.788 / 0.3);
