#root {
  width: 100%;
  max-width: 100%;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  overflow-x: hidden;
}

@media (max-width: 1024px) {
  [data-slot="table"] {
    min-width: 680px;
  }
}

@media (max-width: 768px) {
  [data-slot="dialog-content"] {
    max-width: calc(100vw - 1rem);
    border-radius: 1rem;
  }
}

.crm-skin {
  color: hsl(var(--foreground));
}

.crm-skin [data-slot="card"] {
  border-radius: 1rem;
}

.crm-skin [data-slot="table-container"] {
  box-shadow: 0 8px 28px rgba(15, 23, 42, 0.06);
}

.dark .crm-skin [data-slot="table-container"] {
  box-shadow: 0 8px 28px rgba(2, 6, 23, 0.42);
}

.crm-skin [data-slot="table-head"] {
  letter-spacing: 0.02em;
}

.crm-skin h1,
.crm-skin h2,
.crm-skin h3 {
  letter-spacing: -0.01em;
}

.crm-page {
  animation: fade-in 180ms ease-out;
}

.crm-page [data-slot="card-header"] {
  padding-bottom: 1rem;
}

.crm-page [data-slot="card-title"] {
  font-size: 1rem;
  letter-spacing: -0.01em;
}

.crm-toolbar {
  border-bottom: 1px solid hsl(var(--border));
  padding-bottom: 0.75rem;
}

.crm-page [data-slot="table-cell"] {
  padding-top: 0.65rem;
  padding-bottom: 0.65rem;
}

.crm-page .text-muted-foreground {
  color: color-mix(in oklab, hsl(var(--foreground)) 58%, transparent);
}

@keyframes fade-in {
  from {
    opacity: 0;
    transform: translateY(2px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes portal-overlay-in {
  from {
    opacity: 0;
    transform: scale(0.98) translateY(8px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

@keyframes portal-overlay-out {
  from {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
  to {
    opacity: 0;
    transform: scale(0.98) translateY(8px);
  }
}

.portal-overlay-enter {
  animation: portal-overlay-in 0.2s ease-out forwards;
}

.portal-overlay-exit {
  animation: portal-overlay-out 0.2s ease-in forwards;
}

.wms-bg-photo {
