}

/* Auth atmospheric scene — wind-swept logistics aurora */
.wms-auth-well {
  will-change: opacity, transform;
}

.wms-auth-well-a {
  background:
    radial-gradient(ellipse 55% 40% at 22% 30%, rgba(34, 211, 238, 0.12), transparent 68%),
    radial-gradient(ellipse 45% 35% at 78% 65%, rgba(59, 130, 246, 0.1), transparent 70%);
  animation: wms-auth-well-drift-a 24s ease-in-out infinite;
}

.wms-auth-well-b {
  background:
    radial-gradient(ellipse 40% 32% at 70% 22%, rgba(251, 146, 60, 0.07), transparent 68%),
    radial-gradient(ellipse 50% 30% at 40% 80%, rgba(129, 140, 248, 0.06), transparent 70%);
  animation: wms-auth-well-drift-b 30s ease-in-out infinite;
}

.wms-auth-well-c {
  background: radial-gradient(ellipse 70% 45% at 50% 50%, rgba(14, 165, 233, 0.04), transparent 72%);
  animation: wms-auth-well-drift-c 20s ease-in-out infinite;
}

@keyframes wms-auth-well-drift-a {
  0%, 100% { opacity: 0.55; transform: translate3d(0, 0, 0) scale(1); }
  50% { opacity: 1; transform: translate3d(2%, -1.5%, 0) scale(1.05); }
}

@keyframes wms-auth-well-drift-b {
  0%, 100% { opacity: 0.4; transform: translate3d(0, 0, 0) scale(1.02); }
  50% { opacity: 0.85; transform: translate3d(-2%, 1.5%, 0) scale(1.06); }
}

@keyframes wms-auth-well-drift-c {
