.app-sidebar-panel {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklab, var(--wms-brand-primary) 55%, #334155) transparent;
}

.app-sidebar-panel::-webkit-scrollbar {
  width: 8px;
}

.app-sidebar-panel::-webkit-scrollbar-track {
  background: color-mix(in oklab, var(--background, #0b1220) 88%, #020617);
  border-left: 1px solid color-mix(in oklab, var(--wms-brand-primary) 22%, transparent);
}

.app-sidebar-panel::-webkit-scrollbar-thumb {
  border-radius: 0;
  border: 1px solid color-mix(in oklab, var(--wms-brand-primary) 45%, transparent);
  background: linear-gradient(
    180deg,
    color-mix(in oklab, var(--wms-brand-primary) 55%, #1e293b),
    color-mix(in oklab, var(--wms-brand-primary) 30%, #0f172a)
  );
  transition: background-color 180ms ease, box-shadow 180ms ease;
}

.app-sidebar-panel::-webkit-scrollbar-thumb:hover {
  background: color-mix(in oklab, var(--wms-brand-primary) 75%, #1e293b);
  box-shadow: 0 0 12px color-mix(in oklab, var(--wms-brand-primary) 40%, transparent);
}

.app-sidebar-panel::-webkit-scrollbar-corner {
  background: transparent;
}

html:not(.dark) .app-sidebar-panel::-webkit-scrollbar-track {
  background: color-mix(in oklab, #f1f5f9 92%, var(--wms-brand-primary));
}

html:not(.dark) .app-sidebar-panel::-webkit-scrollbar-thumb {
  background: linear-gradient(
    180deg,
    color-mix(in oklab, var(--wms-brand-primary) 45%, #cbd5e1),
    color-mix(in oklab, var(--wms-brand-primary) 25%, #e2e8f0)
  );
}

.app-sidebar-panel::after {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  inset-inline-end: 0;
  width: 1px;
  background: linear-gradient(
    to bottom,
    color-mix(in oklab, var(--wms-brand-primary) 55%, transparent) 0%,
    color-mix(in oklab, var(--wms-brand-primary) 18%, transparent) 45%,
    transparent 80%
  );
  pointer-events: none;
}

.app-navbar-panel::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 1px;
  background: linear-gradient(
    90deg,
    color-mix(in oklab, var(--wms-brand-primary) 50%, transparent) 0%,
    color-mix(in oklab, var(--wms-brand-primary) 14%, transparent) 40%,
    transparent 75%
  );
  pointer-events: none;
}

html[dir='rtl'] .app-navbar-panel::after {
  background: linear-gradient(
    -90deg,
    color-mix(in oklab, var(--wms-brand-primary) 50%, transparent) 0%,
    color-mix(in oklab, var(--wms-brand-primary) 14%, transparent) 40%,
    transparent 75%
  );
}

