    linear-gradient(currentColor, currentColor) top right / 1.5px 0.28rem no-repeat,
    linear-gradient(currentColor, currentColor) bottom left / 0.28rem 1.5px no-repeat,
    linear-gradient(currentColor, currentColor) bottom left / 1.5px 0.28rem no-repeat,
    linear-gradient(currentColor, currentColor) bottom right / 0.28rem 1.5px no-repeat,
    linear-gradient(currentColor, currentColor) bottom right / 1.5px 0.28rem no-repeat;
  box-shadow: 0 0 6px color-mix(in oklab, var(--wms-ops-accent, #22d3ee) 28%, transparent);
  animation: wms-ops-btn-terminal-frame 1.1s steps(4, end) infinite;
}

