/* ?? Ops terminal toast / system log notifications (Sonner) ?? */
.wms-ops-toaster {
  --wms-ops-toast-font: 'Cascadia Code', 'Cascadia Mono', 'JetBrains Mono', 'Fira Code', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --wms-ops-toast-accent: #0891b2;
  --wms-ops-toast-accent-glow: rgba(8, 145, 178, 0.38);
  --wms-ops-toast-bg: rgba(241, 245, 249, 0.98);
  --wms-ops-toast-header-bg: rgba(8, 145, 178, 0.08);
  --wms-ops-toast-border: rgba(8, 145, 178, 0.28);
  --wms-ops-toast-text: #0b1220;
  --wms-ops-toast-muted: rgba(15, 23, 42, 0.58);
  --wms-ops-toast-prompt: #0e7490;
  --wms-ops-toast-ok: #047857;
  --wms-ops-toast-ok-bg: rgba(16, 185, 129, 0.1);
  --wms-ops-toast-info: #0369a1;
  --wms-ops-toast-info-bg: rgba(14, 165, 233, 0.1);
  --wms-ops-toast-warn: #b45309;
  --wms-ops-toast-warn-bg: rgba(245, 158, 11, 0.12);
  --wms-ops-toast-err: #b91c1c;
  --wms-ops-toast-err-bg: rgba(239, 68, 68, 0.1);
  --wms-ops-toast-run: #0e7490;
  --wms-ops-toast-run-bg: rgba(8, 145, 178, 0.1);
  font-family: var(--wms-ops-toast-font);
}

.dark .wms-ops-toaster {
  --wms-ops-toast-accent: #00f2ff;
  --wms-ops-toast-accent-glow: rgba(0, 242, 255, 0.34);
  --wms-ops-toast-bg: rgba(6, 11, 17, 0.96);
  --wms-ops-toast-header-bg: rgba(0, 242, 255, 0.06);
  --wms-ops-toast-border: rgba(0, 242, 255, 0.2);
  --wms-ops-toast-text: #d7e8f3;
  --wms-ops-toast-muted: rgba(203, 213, 225, 0.58);
  --wms-ops-toast-prompt: #5ffbff;
  --wms-ops-toast-ok: #34d399;
  --wms-ops-toast-ok-bg: rgba(52, 211, 153, 0.12);
  --wms-ops-toast-info: #38bdf8;
  --wms-ops-toast-info-bg: rgba(56, 189, 248, 0.12);
  --wms-ops-toast-warn: #fbbf24;
  --wms-ops-toast-warn-bg: rgba(251, 191, 36, 0.12);
  --wms-ops-toast-err: #fb7185;
  --wms-ops-toast-err-bg: rgba(251, 113, 133, 0.12);
  --wms-ops-toast-run: #5ffbff;
  --wms-ops-toast-run-bg: rgba(0, 242, 255, 0.1);
}

.wms-ops-toaster [data-sonner-toast][data-styled='true'] {
  position: relative;
  overflow: hidden;
  border-radius: 0 !important;
  border: 1px solid var(--wms-ops-toast-border) !important;
  background:
    linear-gradient(180deg, var(--wms-ops-toast-header-bg) 0 1.35rem, transparent 1.35rem),
    var(--wms-ops-toast-bg) !important;
  color: var(--wms-ops-toast-text) !important;
  padding: 1.55rem 2.1rem 0.72rem 0.72rem !important;
  box-shadow:
    inset 0 0 0 1px color-mix(in oklab, var(--wms-ops-toast-accent) 8%, transparent),
    inset 0 1px 0 color-mix(in oklab, var(--wms-ops-toast-accent) 18%, transparent),
    0 0 16px color-mix(in oklab, var(--wms-ops-toast-accent-glow) 50%, transparent),
    0 12px 30px rgba(2, 6, 23, 0.22) !important;
  align-items: flex-start !important;
  gap: 0.55rem !important;
  font-family: var(--wms-ops-toast-font) !important;
}

.dark .wms-ops-toaster [data-sonner-toast][data-styled='true'] {
  box-shadow:
    inset 0 0 0 1px color-mix(in oklab, var(--wms-ops-toast-accent) 12%, transparent),
    inset 0 1px 0 color-mix(in oklab, var(--wms-ops-toast-accent) 22%, transparent),
    0 0 22px color-mix(in oklab, var(--wms-ops-toast-accent-glow) 65%, transparent),
    0 14px 34px rgba(0, 0, 0, 0.45) !important;
}

.wms-ops-toaster [data-sonner-toast][data-styled='true']::before {
  content: 'SYS // NOTIFY';
  position: absolute;
  top: 0;
  left: 0;
  right: 2.4rem;
  height: 1.35rem;
  display: flex;
  align-items: center;
  padding: 0 0.55rem;
  border-bottom: 1px solid color-mix(in oklab, var(--wms-ops-toast-accent) 18%, var(--wms-ops-toast-border));
  font-family: var(--wms-ops-toast-font);
  font-size: 0.5rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: color-mix(in oklab, var(--wms-ops-toast-accent) 72%, var(--wms-ops-toast-text));
  pointer-events: none;
  z-index: 2;
}

.wms-ops-toaster [data-sonner-toast][data-styled='true']::after {
  content: '';
  position: absolute;
  inset: 1.35rem 0 0;
  background-image:
    linear-gradient(color-mix(in oklab, var(--wms-ops-toast-accent) 5%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in oklab, var(--wms-ops-toast-accent) 5%, transparent) 1px, transparent 1px);
  background-size: 12px 12px;
  opacity: 0.3;
  pointer-events: none;
}

.dark .wms-ops-toaster [data-sonner-toast][data-styled='true']::after {
  opacity: 0.22;
  background-image: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    color-mix(in oklab, var(--wms-ops-toast-accent) 4%, transparent) 2px,
    color-mix(in oklab, var(--wms-ops-toast-accent) 4%, transparent) 3px
  );
  background-size: auto;
}

.wms-ops-toaster [data-sonner-toast][data-type='success'] {
  border-left: 3px solid var(--wms-ops-toast-ok) !important;
}

.wms-ops-toaster [data-sonner-toast][data-type='info'],
.wms-ops-toaster [data-sonner-toast][data-type='default'] {
  border-left: 3px solid var(--wms-ops-toast-info) !important;
}

.wms-ops-toaster [data-sonner-toast][data-type='warning'] {
  border-left: 3px solid var(--wms-ops-toast-warn) !important;
}

.wms-ops-toaster [data-sonner-toast][data-type='error'] {
  border-left: 3px solid var(--wms-ops-toast-err) !important;
}

.wms-ops-toaster [data-sonner-toast][data-type='loading'] {
  border-left: 3px solid var(--wms-ops-toast-run) !important;
}

.wms-ops-toaster [data-sonner-toast] [data-icon] {
  position: relative;
  z-index: 1;
  height: auto !important;
  width: auto !important;
  margin-top: 0.05rem !important;
  padding-right: 0.45rem;
  border-right: 1px solid color-mix(in oklab, var(--wms-ops-toast-accent) 16%, var(--wms-ops-toast-border));
}

.wms-ops-toast__loading {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  color: var(--wms-ops-toast-run);
}

.wms-ops-toast__tag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.02rem;
  min-width: 2.45rem;
  padding: 0.14rem 0.2rem;
  border: 1px solid color-mix(in oklab, currentColor 32%, transparent);
  background: color-mix(in oklab, currentColor 8%, transparent);
  font-family: var(--wms-ops-toast-font);
  font-size: 0.5625rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1;
  text-shadow: 0 0 10px color-mix(in oklab, currentColor 24%, transparent);
}

.wms-ops-toast__tag-bracket {
  opacity: 0.55;
  font-weight: 500;
}

.wms-ops-toast__tag--success {
  color: var(--wms-ops-toast-ok);
  background: var(--wms-ops-toast-ok-bg);
  border-color: color-mix(in oklab, var(--wms-ops-toast-ok) 38%, transparent);
}

.wms-ops-toast__tag--info {
  color: var(--wms-ops-toast-info);
  background: var(--wms-ops-toast-info-bg);
  border-color: color-mix(in oklab, var(--wms-ops-toast-info) 38%, transparent);
}

.wms-ops-toast__tag--warn {
  color: var(--wms-ops-toast-warn);
  background: var(--wms-ops-toast-warn-bg);
  border-color: color-mix(in oklab, var(--wms-ops-toast-warn) 38%, transparent);
}

.wms-ops-toast__tag--error {
  color: var(--wms-ops-toast-err);
  background: var(--wms-ops-toast-err-bg);
  border-color: color-mix(in oklab, var(--wms-ops-toast-err) 38%, transparent);
}

.wms-ops-toast__tag--run {
  color: var(--wms-ops-toast-run);
  background: var(--wms-ops-toast-run-bg);
  border-color: color-mix(in oklab, var(--wms-ops-toast-run) 38%, transparent);
}

.wms-ops-toaster [data-sonner-toast] [data-content] {
  position: relative;
  z-index: 1;
  min-width: 0;
  padding-top: 0.02rem;
}

.wms-ops-toaster [data-sonner-toast] [data-title] {
  font-family: var(--wms-ops-toast-font) !important;
  font-size: 0.75rem !important;
  font-weight: 600 !important;
  letter-spacing: 0.01em;
  line-height: 1.5 !important;
  color: var(--wms-ops-toast-text) !important;
}

.wms-ops-toaster [data-sonner-toast] [data-title]::before {
  content: '> ';
  color: var(--wms-ops-toast-prompt);
  font-weight: 700;
  text-shadow: 0 0 8px color-mix(in oklab, var(--wms-ops-toast-prompt) 35%, transparent);
}

.dark .wms-ops-toaster [data-sonner-toast] [data-title] {
  text-shadow: 0 0 12px color-mix(in oklab, var(--wms-ops-toast-text) 8%, transparent);
}

.wms-ops-toaster [data-sonner-toast] [data-description] {
  margin-top: 0.15rem;
  padding-left: 0.95rem;
  font-family: var(--wms-ops-toast-font) !important;
  font-size: 0.6875rem !important;
  line-height: 1.45 !important;
  color: var(--wms-ops-toast-muted) !important;
}

.wms-ops-toaster [data-sonner-toast] [data-description]::before {
  content: ':: ';
  color: color-mix(in oklab, var(--wms-ops-toast-prompt) 70%, var(--wms-ops-toast-muted));
}

.wms-ops-toaster [data-sonner-toast] [data-close-button] {
  top: 0.2rem !important;
  right: 0.35rem !important;
  left: auto !important;
  width: 1.05rem !important;
  height: 1.05rem !important;
  border-radius: 0 !important;
  border: 1px solid color-mix(in oklab, var(--wms-ops-toast-accent) 28%, var(--wms-ops-toast-border)) !important;
  background: color-mix(in oklab, var(--wms-ops-toast-bg) 90%, transparent) !important;
  color: color-mix(in oklab, var(--wms-ops-toast-text) 68%, transparent) !important;
  transform: none !important;
  font-family: var(--wms-ops-toast-font) !important;
  font-size: 0.625rem !important;
  z-index: 3;
}

.wms-ops-toaster [data-sonner-toast] [data-close-button]:hover {
  border-color: color-mix(in oklab, var(--wms-ops-toast-accent) 55%, var(--wms-ops-toast-border)) !important;
  color: var(--wms-ops-toast-accent) !important;
  background: color-mix(in oklab, var(--wms-ops-toast-accent) 10%, var(--wms-ops-toast-bg)) !important;
  box-shadow: 0 0 10px color-mix(in oklab, var(--wms-ops-toast-accent-glow) 45%, transparent);
}

.wms-ops-toaster [data-sonner-toast] [data-button],
.wms-ops-toaster [data-sonner-toast] [data-cancel] {
  border-radius: 0 !important;
  font-family: var(--wms-ops-toast-font) !important;
  font-size: 0.625rem !important;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.wms-ops-toaster [data-sonner-toast] [data-button] {
  border: 1px solid color-mix(in oklab, var(--wms-ops-toast-accent) 42%, transparent) !important;
  background: color-mix(in oklab, var(--wms-ops-toast-accent) 12%, var(--wms-ops-toast-bg)) !important;
  color: var(--wms-ops-toast-text) !important;
}

.wms-ops-toaster [data-sonner-toast] [data-cancel] {
  border: 1px solid var(--wms-ops-toast-border) !important;
  background: transparent !important;
  color: var(--wms-ops-toast-muted) !important;
}

@media (max-width: 640px) {
  .wms-ops-toaster {
    --width: calc(100vw - 1.5rem);
  }
}

