.wms-ops-delete-dialog__header {
  border-bottom-color: color-mix(in oklab, #ef4444 32%, var(--wms-ops-card-border)) !important;
}

.wms-ops-delete-dialog__close {
  position: absolute;
  top: 0.2rem;
