  border: 1px solid color-mix(in oklab, var(--wms-ops-accent) 28%, var(--wms-ops-card-border));
  background: color-mix(in oklab, var(--wms-ops-field-bg) 90%, transparent);
  color: color-mix(in oklab, var(--wms-ops-accent) 70%, hsl(var(--foreground)));
