  background: color-mix(in oklab, #ef4444 10%, var(--wms-ops-field-bg));
  padding: 0.125rem 0.4rem;
  font-weight: 700;
  color: color-mix(in oklab, #fecaca 88%, hsl(var(--foreground)));
  word-break: break-all;
}

.wms-ops-delete-dialog__suffix {
  display: inline;
}

.wms-ops-delete-dialog__footer {
  border-top-color: color-mix(in oklab, #ef4444 18%, var(--wms-ops-card-border)) !important;
}

.wms-ops-delete-dialog .wms-ops-delete-btn {
  z-index: 0;
  border: none !important;
  background: color-mix(in oklab, #ef4444 7%, var(--wms-ops-field-bg)) !important;
  color: color-mix(in oklab, #fca5a5 48%, hsl(var(--foreground))) !important;
  box-shadow:
    inset 0 0 0 1px color-mix(in oklab, #ef4444 20%, transparent),
    0 0 10px color-mix(in oklab, #ef4444 5%, transparent);
  text-shadow: none;
  animation: none;
}

.wms-ops-delete-dialog .wms-ops-delete-btn::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  background: linear-gradient(
    105deg,
    transparent 36%,
    color-mix(in oklab, #ef4444 18%, transparent) 46%,
    color-mix(in oklab, #fef08a 42%, #f87171) 50%,
    color-mix(in oklab, #ef4444 18%, transparent) 54%,
    transparent 64%
  );
  transform: translateX(-140%);
  opacity: 0;
  pointer-events: none;
  animation: wms-ops-delete-btn-shimmer-idle 16s ease-in-out infinite;
}

.wms-ops-delete-dialog .wms-ops-delete-btn__label {
  position: relative;
  z-index: 1;
}

.wms-ops-delete-dialog .wms-ops-delete-btn::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  background: repeating-linear-gradient(
    180deg,
    transparent 0,
    transparent 4px,
    color-mix(in oklab, #ef4444 10%, transparent) 4px,
    color-mix(in oklab, #ef4444 10%, transparent) 5px
  );
  opacity: 0;
  mix-blend-mode: screen;
  pointer-events: none;
}

.wms-ops-delete-dialog .wms-ops-delete-btn:hover:not(:disabled) {
  color: #fff !important;
  background: color-mix(in oklab, #ef4444 22%, #140606) !important;
  box-shadow:
    inset 0 0 0 1px color-mix(in oklab, #f87171 55%, transparent),
    0 0 16px color-mix(in oklab, #ef4444 32%, transparent),
    0 0 28px color-mix(in oklab, #ef4444 14%, transparent);
  text-shadow: 0 0 8px color-mix(in oklab, #fca5a5 70%, transparent);
  transform: translateY(-1px);
  animation: wms-ops-delete-btn-glitch 3s steps(1, end) infinite;
}

.wms-ops-delete-dialog .wms-ops-delete-btn:hover:not(:disabled)::before {
  animation: wms-ops-delete-btn-shimmer-hover 9s ease-in-out infinite;
}

.wms-ops-delete-dialog .wms-ops-delete-btn:hover:not(:disabled)::after {
  animation: wms-ops-delete-btn-glitch-scan 3s steps(1, end) infinite;
}

.wms-ops-delete-dialog .wms-ops-delete-btn:hover:not(:disabled) .wms-ops-delete-btn__label {
  animation: wms-ops-delete-btn-label-glitch 3s steps(1, end) infinite;
}

.wms-ops-delete-dialog .wms-ops-delete-btn:disabled {
  opacity: 0.42;
  animation: none;
  cursor: not-allowed;
}

.wms-ops-delete-dialog .wms-ops-delete-btn:disabled::before {
  animation: none;
}

@keyframes wms-ops-delete-btn-shimmer-idle {
  0%, 82%, 100% {
    transform: translateX(-140%);
    opacity: 0;
  }
  83% {
    opacity: 0.45;
  }
  94% {
    transform: translateX(140%);
    opacity: 0.45;
  }
  95%, 100% {
    transform: translateX(140%);
    opacity: 0;
  }
}

@keyframes wms-ops-delete-btn-shimmer-hover {
  0%, 70%, 100% {
    transform: translateX(-140%);
    opacity: 0;
  }
  71% {
    opacity: 0.75;
  }
  86% {
    transform: translateX(140%);
    opacity: 0.75;
  }
  87%, 100% {
    transform: translateX(140%);
    opacity: 0;
  }
}

@keyframes wms-ops-delete-btn-glitch {
  0%, 84%, 100% {
    transform: translateY(-1px) translateX(0);
    filter: none;
  }
  85% {
    transform: translateY(-1px) translateX(-2px);
    filter: drop-shadow(2px 0 color-mix(in oklab, #f43f5e 75%, transparent))
      drop-shadow(-2px 0 color-mix(in oklab, #22d3ee 55%, transparent));
  }
  86% {
    transform: translateY(-1px) translateX(2px);
  }
  87% {
    transform: translateY(-2px) translateX(-1px);
    filter: drop-shadow(-1px 0 color-mix(in oklab, #f43f5e 65%, transparent))
      drop-shadow(1px 0 color-mix(in oklab, #22d3ee 45%, transparent));
  }
  88% {
    transform: translateY(-1px) translateX(0);
    filter: none;
  }
}

@keyframes wms-ops-delete-btn-glitch-scan {
  0%, 83%, 100% {
    opacity: 0;
    transform: translateY(0);
  }
  84%, 89% {
    opacity: 0.35;
    transform: translateY(2px);
  }
  85%, 90% {
    opacity: 0.22;
    transform: translateY(-2px);
  }
}

@keyframes wms-ops-delete-btn-label-glitch {
  0%, 84%, 100% {
    text-shadow: 0 0 8px color-mix(in oklab, #fca5a5 70%, transparent);
    transform: translateX(0);
  }
  85% {
    text-shadow:
      -2px 0 color-mix(in oklab, #f43f5e 80%, transparent),
      2px 0 color-mix(in oklab, #22d3ee 55%, transparent);
    transform: translateX(-1px);
  }
  86% {
    text-shadow:
      2px 0 color-mix(in oklab, #f43f5e 80%, transparent),
      -2px 0 color-mix(in oklab, #22d3ee 55%, transparent);
    transform: translateX(1px);
  }
  87% {
    transform: translateX(-1px);
  }
  88% {
    text-shadow: 0 0 8px color-mix(in oklab, #fca5a5 70%, transparent);
    transform: translateX(0);
  }
}

