  z-index: 1;
}

.wms-ops-reports-status {
  border: 1px solid color-mix(in oklab, var(--wms-ops-circuit-accent) 24%, var(--wms-ops-card-border));
  background: color-mix(in oklab, var(--wms-ops-field-bg) 88%, transparent);
