}

.wms-ops-reports-status__line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.15rem;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.wms-ops-reports-status__prompt,
.wms-ops-reports-status__ready {
  color: color-mix(in oklab, var(--wms-ops-circuit-accent) 82%, hsl(var(--foreground)));
}

.wms-ops-reports-status__label {
  color: hsl(var(--foreground));
}

.wms-ops-reports-status__sep {
  color: color-mix(in oklab, hsl(var(--foreground)) 40%, transparent);
}

.wms-ops-reports-status__cursor {
