}

.wms-ops-reports-status__hint {
  margin-top: 0.45rem;
  font-size: 0.6875rem;
  line-height: 1.45;
  letter-spacing: 0.04em;
  color: color-mix(in oklab, hsl(var(--foreground)) 58%, transparent);
}

.wms-ops-reports-section {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.wms-ops-reports-section__header {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

@media (min-width: 768px) {
  .wms-ops-reports-section__header {
    flex-direction: row;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1rem;
  }
}

.wms-ops-reports-section__meta {
  max-width: 28rem;
  text-align: left;
}

.wms-ops-reports-section__code {
  display: inline-block;
  margin-bottom: 0.25rem;
  border: 1px solid color-mix(in oklab, var(--wms-ops-circuit-accent) 28%, var(--wms-ops-card-border));
  background: color-mix(in oklab, var(--wms-ops-circuit-accent) 8%, var(--wms-ops-field-bg));
  padding: 0.1rem 0.4rem;
  font-size: 0.5625rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: color-mix(in oklab, var(--wms-ops-circuit-accent) 78%, hsl(var(--foreground)));
}

.wms-ops-reports-section__grid {
  display: grid;
  gap: 0.875rem;
}

@media (min-width: 768px) {
  .wms-ops-reports-section__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1280px) {
  .wms-ops-reports-section__grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.wms-ops-reports-module {
  position: relative;
  display: flex;
  min-height: 100%;
  flex-direction: column;
  gap: 0.75rem;
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--wms-ops-circuit-accent) 18%, var(--wms-ops-card-border));
  background: color-mix(in oklab, var(--wms-ops-field-bg) 90%, transparent);
  padding: 0.875rem;
  text-decoration: none;
  color: inherit;
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease;
}

.wms-ops-reports-module:hover,
.wms-ops-reports-module:focus-visible {
  border-color: color-mix(in oklab, var(--wms-ops-circuit-accent) 48%, transparent);
  box-shadow:
    0 0 18px color-mix(in oklab, var(--wms-ops-circuit-accent) 14%, transparent),
    inset 0 0 0 1px color-mix(in oklab, var(--wms-ops-circuit-accent) 12%, transparent);
  transform: translateY(-1px);
  outline: none;
}

.wms-ops-reports-module__frame {
  pointer-events: none;
  position: absolute;
  inset: 0;
}

.wms-ops-reports-module__corner {
  position: absolute;
  width: 0.75rem;
  height: 0.75rem;
  border-color: color-mix(in oklab, var(--wms-ops-circuit-accent) 55%, transparent);
  border-style: solid;
  opacity: 0.55;
  transition: opacity 160ms ease, filter 160ms ease;
}

.wms-ops-reports-module:hover .wms-ops-reports-module__corner,
.wms-ops-reports-module:focus-visible .wms-ops-reports-module__corner {
  opacity: 0.95;
  filter: drop-shadow(0 0 5px var(--wms-ops-circuit-glow));
}

.wms-ops-reports-module__corner--tl {
  top: 0.35rem;
  left: 0.35rem;
  border-width: 2px 0 0 2px;
}

.wms-ops-reports-module__corner--tr {
  top: 0.35rem;
  right: 0.35rem;
  border-width: 2px 2px 0 0;
}

.wms-ops-reports-module__corner--bl {
  bottom: 0.35rem;
  left: 0.35rem;
  border-width: 0 0 2px 2px;
}

.wms-ops-reports-module__corner--br {
  right: 0.35rem;
  bottom: 0.35rem;
  border-width: 0 2px 2px 0;
}

.wms-ops-reports-module__scan {
  position: absolute;
  inset: 0;
  opacity: 0;
  transform: translateX(-120%);
  will-change: transform, opacity;
  pointer-events: none;
  background: linear-gradient(
    90deg,
    transparent 0%,
    color-mix(in oklab, var(--wms-ops-circuit-accent) 18%, transparent) 48%,
    color-mix(in oklab, var(--wms-ops-circuit-accent) 28%, transparent) 50%,
    color-mix(in oklab, var(--wms-ops-circuit-accent) 18%, transparent) 52%,
    transparent 100%
  );
}

.wms-ops-reports-module:hover .wms-ops-reports-module__scan,
.wms-ops-reports-module:focus-visible .wms-ops-reports-module__scan {
  animation: wms-ops-reports-module-scan-cycle 11.4s linear infinite;
}

.wms-ops-reports-module__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.wms-ops-reports-module__index {
  font-size: 0.625rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: color-mix(in oklab, var(--wms-ops-circuit-accent) 72%, hsl(var(--foreground)));
}

.wms-ops-reports-module__badge {
  font-size: 0.5625rem;
  letter-spacing: 0.08em;
}

.wms-ops-reports-module__body {
  display: flex;
  flex: 1 1 auto;
  align-items: flex-start;
  gap: 0.65rem;
}

.wms-ops-reports-module__icon {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border: 1px solid color-mix(in oklab, var(--wms-ops-circuit-accent) 32%, var(--wms-ops-card-border));
  background: color-mix(in oklab, var(--wms-ops-circuit-accent) 8%, transparent);
  padding: 0.45rem;
  color: var(--wms-ops-circuit-accent);
  box-shadow: 0 0 10px var(--wms-ops-circuit-glow);
}

.wms-ops-reports-module__title {
  font-size: 0.8125rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: hsl(var(--foreground));
}

.wms-ops-reports-module:hover .wms-ops-reports-module__title,
.wms-ops-reports-module:focus-visible .wms-ops-reports-module__title {
  text-shadow: 0 0 10px color-mix(in oklab, var(--wms-ops-circuit-accent) 35%, transparent);
}

.wms-ops-reports-module:hover .wms-ops-reports-module__glitch,
.wms-ops-reports-module:focus-visible .wms-ops-reports-module__glitch {
  animation: wms-ops-reports-glitch 3.6s steps(1, end) infinite;
}

.wms-ops-reports-module:hover .wms-ops-reports-module__icon.wms-ops-reports-module__glitch,
.wms-ops-reports-module:focus-visible .wms-ops-reports-module__icon.wms-ops-reports-module__glitch {
  animation-delay: 0.08s;
  text-shadow: 0 0 12px var(--wms-ops-circuit-glow);
}

.wms-ops-reports-module:hover .wms-ops-reports-module__index.wms-ops-reports-module__glitch,
.wms-ops-reports-module:focus-visible .wms-ops-reports-module__index.wms-ops-reports-module__glitch {
  animation-delay: 0.14s;
}

.wms-ops-reports-module:hover .wms-ops-reports-module__route-code.wms-ops-reports-module__glitch,
.wms-ops-reports-module:focus-visible .wms-ops-reports-module__route-code.wms-ops-reports-module__glitch {
  animation-delay: 0.2s;
}

.wms-ops-reports-module:hover .wms-ops-reports-module__corner.wms-ops-reports-module__glitch,
.wms-ops-reports-module:focus-visible .wms-ops-reports-module__corner.wms-ops-reports-module__glitch {
  animation-delay: 0.04s;
}

.wms-ops-reports-module__desc {
  margin-top: 0.3rem;
  font-size: 0.6875rem;
  line-height: 1.45;
  letter-spacing: 0.02em;
  text-transform: none;
  color: color-mix(in oklab, hsl(var(--foreground)) 58%, transparent);
}

.wms-ops-reports-module__route {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.5625rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: color-mix(in oklab, hsl(var(--foreground)) 48%, transparent);
}

.wms-ops-reports-module__route-prefix {
  color: color-mix(in oklab, var(--wms-ops-circuit-accent) 62%, hsl(var(--foreground)));
}

.wms-ops-reports-module__route-code {
  color: color-mix(in oklab, var(--wms-ops-circuit-accent) 78%, hsl(var(--foreground)));
}

.wms-ops-reports-module__action {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  border: 1px solid color-mix(in oklab, var(--wms-ops-circuit-accent) 22%, var(--wms-ops-card-border));
  background: color-mix(in oklab, var(--wms-ops-circuit-accent) 5%, var(--wms-ops-field-bg));
  padding: 0.4rem 0.55rem;
  font-size: 0.625rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: color-mix(in oklab, var(--wms-ops-circuit-accent) 80%, hsl(var(--foreground)));
  transition: background-color 160ms ease, border-color 160ms ease;
}

.wms-ops-reports-module:hover .wms-ops-reports-module__action,
.wms-ops-reports-module:focus-visible .wms-ops-reports-module__action {
  border-color: color-mix(in oklab, var(--wms-ops-circuit-accent) 42%, transparent);
  background: color-mix(in oklab, var(--wms-ops-circuit-accent) 12%, var(--wms-ops-field-bg));
}

@keyframes wms-ops-reports-cursor-blink {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

@keyframes wms-ops-reports-module-scan-cycle {
  0% {
    opacity: 0;
    transform: translateX(-120%);
  }
  0.5% {
    opacity: 1;
    transform: translateX(-120%);
  }
  12.28% {
    opacity: 1;
    transform: translateX(120%);
  }
  13.5% {
    opacity: 0;
    transform: translateX(120%);
  }
  100% {
    opacity: 0;
    transform: translateX(-120%);
  }
}

@keyframes wms-ops-reports-glitch {
  0%, 88%, 100% {
    transform: none;
    opacity: 1;
    filter: none;
  }
  89% {
    transform: translateX(-1px);
    opacity: 0.84;
    filter: hue-rotate(10deg) saturate(1.15);
  }
  90% {
    transform: translateX(1px);
    opacity: 1;
    filter: hue-rotate(-6deg);
  }
  91% {
    transform: none;
    filter: none;
  }
  94% {
    transform: translateY(-1px);
    opacity: 0.9;
  }
  95% {
    transform: none;
    opacity: 1;
  }
}

