/* neon top edge */
.wms-ops-dashboard-page .wms-ops-dashboard-panel::before,
.wms-ops-dashboard-page .wms-ops-dashboard-hero::before,
.wms-ops-dashboard-page .wms-ops-dashboard-section::before,
.wms-ops-dashboard-page .wms-ops-dashboard-metric::before,
.wms-ops-dashboard-page .wms-ops-dashboard-module::before,
.wms-ops-dashboard-page .wms-ops-dashboard-activity__row::before {
  content: '';
  pointer-events: none;
  position: absolute;
  top: 0;
  left: 0;
  right: 14px;
  height: 2px;
  z-index: 2;
  background: linear-gradient(90deg, var(--cyb-cyan) 0%, color-mix(in oklab, var(--cyb-magenta) 85%, transparent) 55%, transparent 90%);
  box-shadow: 0 0 14px color-mix(in oklab, var(--cyb-cyan) 60%, transparent);
  opacity: 0.9;
}

.wms-ops-dashboard-terminal {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  isolation: isolate;
}

/* ambient: neon haze + perspective grid + scanlines + roaming sweep */
.wms-ops-dashboard-terminal__scanlines {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
  background:
    radial-gradient(ellipse 60% 40% at 8% -5%, color-mix(in oklab, var(--cyb-cyan) 14%, transparent), transparent 70%),
    radial-gradient(ellipse 50% 38% at 95% 8%, color-mix(in oklab, var(--cyb-magenta) 11%, transparent), transparent 70%),
    radial-gradient(ellipse 55% 45% at 50% 110%, color-mix(in oklab, var(--cyb-violet) 12%, transparent), transparent 70%),
    linear-gradient(color-mix(in oklab, var(--cyb-cyan) 7%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in oklab, var(--cyb-cyan) 7%, transparent) 1px, transparent 1px);
  background-size: 100% 100%, 100% 100%, 100% 100%, 44px 44px, 44px 44px;
  -webkit-mask-image: linear-gradient(180deg, black, black 80%, transparent);
  mask-image: linear-gradient(180deg, black, black 80%, transparent);
}

.wms-ops-dashboard-terminal__scanlines::before {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    180deg,
    transparent 0,
    transparent 3px,
    color-mix(in oklab, var(--cyb-cyan) 5%, transparent) 3px,
    color-mix(in oklab, var(--cyb-cyan) 5%, transparent) 4px
  );
  opacity: 0.5;
}

.wms-ops-dashboard-terminal__scanlines::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  height: 140px;
  background: linear-gradient(180deg, transparent, color-mix(in oklab, var(--cyb-cyan) 9%, transparent) 50%, transparent);
  animation: cyb-sweep 9s linear infinite;
}

@keyframes cyb-sweep {
  0% { top: -140px; }
  100% { top: 100%; }
}

.wms-ops-dashboard-terminal > *:not(.wms-ops-dashboard-terminal__scanlines) {
  position: relative;
  z-index: 1;
}

.wms-ops-dashboard-hero {
  overflow: hidden;
  padding: 1.4rem 1.5rem 1.5rem;
  background:
    radial-gradient(circle at 10% -10%, color-mix(in oklab, var(--cyb-cyan) 20%, transparent), transparent 46%),
    radial-gradient(circle at 92% 115%, color-mix(in oklab, var(--cyb-magenta) 16%, transparent), transparent 42%),
    linear-gradient(165deg, color-mix(in oklab, var(--cyb-cyan) 8%, var(--cyb-surface-2)) 0%, var(--cyb-surface) 45%, var(--cyb-nested) 100%);
  box-shadow:
    inset 0 0 60px color-mix(in oklab, var(--cyb-cyan) 8%, transparent),
    inset 0 0 0 1px color-mix(in oklab, var(--cyb-cyan) 12%, transparent);
}

/* diagonal hazard stripes strip on hero right edge */
.wms-ops-dashboard-hero::after {
  content: '';
  pointer-events: none;
  position: absolute;
  top: 0;
  bottom: 0;
  right: 0;
  width: 10px;
  background: repeating-linear-gradient(
    -45deg,
    color-mix(in oklab, var(--cyb-cyan) 45%, transparent) 0 6px,
    transparent 6px 14px
  );
  opacity: 0.55;
}

.wms-ops-dashboard-panel {
  overflow: hidden;
  padding: 1rem 1.1rem 1.1rem;
}

.wms-ops-dashboard-panel--metrics {
  padding-bottom: 1.15rem;
}

.wms-ops-dashboard-panel__content {
  position: relative;
  z-index: 1;
}

.wms-ops-dashboard-panel__frame,
.wms-ops-dashboard-section__frame {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
}

.wms-ops-dashboard-panel__corner,
.wms-ops-dashboard-section__corner {
  position: absolute;
  width: 1.1rem;
  height: 1.1rem;
  border-color: var(--cyb-cyan);
  filter: drop-shadow(0 0 5px color-mix(in oklab, var(--cyb-cyan) 70%, transparent));
}

.wms-ops-dashboard-panel__corner--tl,
.wms-ops-dashboard-section__corner--tl { top: 0; left: 0; border-top: 2px solid; border-left: 2px solid; }
.wms-ops-dashboard-panel__corner--tr,
.wms-ops-dashboard-section__corner--tr { top: 0; right: 0; border-top: 2px solid; border-right: 2px solid; border-color: var(--cyb-magenta); }
.wms-ops-dashboard-panel__corner--bl,
.wms-ops-dashboard-section__corner--bl { bottom: 0; left: 0; border-bottom: 2px solid; border-left: 2px solid; border-color: var(--cyb-magenta); }
.wms-ops-dashboard-panel__corner--br,
.wms-ops-dashboard-section__corner--br { bottom: 0; right: 0; border-bottom: 2px solid; border-right: 2px solid; }

.wms-ops-dashboard-panel__heading {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin-bottom: 0.9rem;
  padding-bottom: 0.65rem;
  border-bottom: 1px solid color-mix(in oklab, var(--cyb-cyan) 24%, transparent);
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--cyb-cyan);
  text-shadow: 0 0 12px color-mix(in oklab, var(--cyb-cyan) 55%, transparent);
}

.wms-ops-dashboard-panel__heading::after {
  content: '';
  flex: 1;
  height: 1px;
  margin-left: 0.6rem;
  background: repeating-linear-gradient(
    90deg,
    color-mix(in oklab, var(--cyb-cyan) 45%, transparent) 0 8px,
    transparent 8px 14px
  );
}

.wms-ops-dashboard-hero__frame,
.wms-ops-dashboard-module__frame {
  pointer-events: none;
  position: absolute;
  inset: 0;
}

.wms-ops-dashboard-hero__corner,
.wms-ops-dashboard-module__corner {
  position: absolute;
  width: 1.1rem;
  height: 1.1rem;
  border-color: var(--cyb-cyan);
  filter: drop-shadow(0 0 5px color-mix(in oklab, var(--cyb-cyan) 70%, transparent));
}

.wms-ops-dashboard-hero__corner--tl,
.wms-ops-dashboard-module__corner--tl { top: 0; left: 0; border-top: 2px solid; border-left: 2px solid; }
.wms-ops-dashboard-hero__corner--tr,
.wms-ops-dashboard-module__corner--tr { top: 0; right: 0; border-top: 2px solid; border-right: 2px solid; border-color: var(--cyb-magenta); }
.wms-ops-dashboard-hero__corner--bl,
.wms-ops-dashboard-module__corner--bl { bottom: 0; left: 0; border-bottom: 2px solid; border-left: 2px solid; border-color: var(--cyb-magenta); }
.wms-ops-dashboard-hero__corner--br,
.wms-ops-dashboard-module__corner--br { bottom: 0; right: 0; border-bottom: 2px solid; border-right: 2px solid; }

.wms-ops-dashboard-hero__glow {
  position: absolute;
  inset: auto -20% -50% -20%;
  height: 80%;
  background: radial-gradient(circle, color-mix(in oklab, var(--cyb-cyan) 22%, transparent), transparent 68%);
  opacity: 0.8;
  animation: cyb-glow-pulse 5s ease-in-out infinite;
}

@keyframes cyb-glow-pulse {
  0%, 100% { opacity: 0.55; }
  50% { opacity: 0.95; }
}

.wms-ops-dashboard-hero__content {
  position: relative;
}

.wms-ops-dashboard-hero__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--cyb-cyan);
  text-shadow: 0 0 12px color-mix(in oklab, var(--cyb-cyan) 60%, transparent);
}

.wms-ops-dashboard-hero__eyebrow::before {
  content: '';
  width: 0.5rem;
  height: 0.5rem;
  background: var(--cyb-cyan);
  clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%);
  box-shadow: 0 0 10px var(--cyb-cyan);
  animation: cyb-glow-pulse 2.4s ease-in-out infinite;
}

.wms-ops-dashboard-hero__title {
  margin-top: 0.4rem;
  font-size: clamp(1.5rem, 2.8vw, 2.3rem);
  font-weight: 800;
  line-height: 1.12;
  letter-spacing: 0.02em;
  color: hsl(var(--foreground));
  text-shadow:
    0 0 22px color-mix(in oklab, var(--cyb-cyan) 45%, transparent),
    2px 0 0 color-mix(in oklab, var(--cyb-magenta) 32%, transparent),
    -2px 0 0 color-mix(in oklab, var(--cyb-cyan) 32%, transparent);
}

.wms-ops-dashboard-hero__subtitle {
  margin-top: 0.5rem;
  max-width: 42rem;
  font-size: 0.8125rem;
  line-height: 1.5;
  color: var(--cyb-text-dim);
}

.wms-ops-dashboard-hero__meta {
  margin-top: 1.1rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 1.25rem;
}

.wms-ops-dashboard-hero__meta-item {
  position: relative;
  min-width: 10rem;
  border: 1px solid color-mix(in oklab, var(--cyb-cyan) 30%, transparent);
  border-left: 3px solid var(--cyb-cyan);
  background: color-mix(in oklab, var(--cyb-nested) 88%, transparent);
  padding: 0.55rem 0.8rem;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%);
  box-shadow:
    inset 0 0 16px color-mix(in oklab, var(--cyb-cyan) 8%, transparent),
    inset 3px 0 12px -4px color-mix(in oklab, var(--cyb-cyan) 55%, transparent);
}

.wms-ops-dashboard-hero__meta-item:nth-child(2) {
  border-left-color: var(--cyb-magenta);
  box-shadow:
    inset 0 0 16px color-mix(in oklab, var(--cyb-magenta) 8%, transparent),
    inset 3px 0 12px -4px color-mix(in oklab, var(--cyb-magenta) 55%, transparent);
}

.wms-ops-dashboard-hero__meta-label,
.wms-ops-dashboard-metric__label {
  font-size: 0.625rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: color-mix(in oklab, var(--cyb-cyan) 78%, hsl(var(--foreground)));
}

.wms-ops-dashboard-hero__meta-value {
  display: block;
  margin-top: 0.2rem;
  font-size: 0.9375rem;
  font-weight: 700;
  color: hsl(var(--foreground));
  text-shadow: 0 0 10px color-mix(in oklab, var(--cyb-cyan) 30%, transparent);
}

.wms-ops-dashboard-page {
  --command-surface: var(--cyb-surface);
  --command-surface-soft: var(--cyb-surface-2);
  --command-border: var(--cyb-line);
  --command-text: hsl(var(--foreground));
  --command-muted: var(--cyb-text-dim);
}

.wms-ops-dashboard-hero__main {
  display: flex;
  flex-direction: column;
  gap: 1.1rem;
}

.wms-ops-dashboard-hero__main--pictorial {
  display: grid;
  grid-template-columns: minmax(16rem, 0.95fr) minmax(18rem, 1.35fr) minmax(12rem, 0.58fr);
  align-items: stretch;
  gap: 0;
  min-height: 13.75rem;
}

.wms-ops-dashboard-hero--pictorial {
  padding: 0;
  overflow: hidden;
}

.wms-ops-dashboard-hero--pictorial .wms-ops-dashboard-hero__content {
  height: 100%;
}

.wms-ops-dashboard-hero--pictorial .wms-ops-dashboard-hero__intro {
  display: flex;
  min-width: 0;
  flex-direction: column;
  justify-content: center;
  padding: 1.35rem 1.45rem;
}

.wms-ops-dashboard-hero--pictorial .wms-ops-dashboard-hero__clock {
  min-width: 0;
  height: 100%;
  justify-content: center;
  clip-path: none;
  border: 0;
  border-inline-start: 1px solid color-mix(in oklab, var(--cyb-cyan) 28%, transparent);
  border-radius: 0;
  background: linear-gradient(145deg, color-mix(in oklab, var(--cyb-nested) 92%, #081b3b), color-mix(in oklab, var(--cyb-surface) 70%, #07142e));
  padding: 1.2rem 1.1rem;
  box-shadow: none;
}

.wms-ops-dashboard-hero__intro {
  min-width: 0;
  flex: 1;
}

.wms-ops-dashboard-hero__greeting {
  margin-top: 0.75rem;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--cyb-cyan);
  text-shadow: 0 0 12px color-mix(in oklab, var(--cyb-cyan) 50%, transparent);
}

.wms-ops-dashboard-hero__visual {
  position: relative;
  min-height: 13.75rem;
  overflow: hidden;
  background-position: 74% center;
  background-size: cover;
}

.wms-ops-dashboard-hero__visual::before,
.wms-ops-dashboard-hero__visual::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.wms-ops-dashboard-hero__visual::before {
  background: linear-gradient(90deg, var(--cyb-surface), transparent 22%, transparent 78%, #07162e 100%);
}

.wms-ops-dashboard-hero__visual::after {
  opacity: 0.34;
  background-image:
    linear-gradient(color-mix(in oklab, var(--cyb-cyan) 22%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in oklab, var(--cyb-cyan) 22%, transparent) 1px, transparent 1px);
  background-size: 28px 28px;
  mask-image: linear-gradient(to bottom, transparent, black 38%, transparent);
}

.wms-ops-dashboard-hero__visual-shade {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgb(3 12 28 / 0.16), rgb(3 12 28 / 0.56));
}

.wms-ops-dashboard-hero__floating {
  position: absolute;
  z-index: 2;
  width: min(10rem, 42%);
  border: 1px solid color-mix(in oklab, var(--cyb-cyan) 45%, transparent);
  background: color-mix(in oklab, #05152e 90%, transparent);
  padding: 0.72rem 0.82rem;
  color: #f8fbff;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%);
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / 0.08),
    0 14px 30px rgb(0 0 0 / 0.28),
    inset 0 0 18px color-mix(in oklab, var(--cyb-cyan) 10%, transparent);
}

.wms-ops-dashboard-hero__floating--operations { left: 9%; top: 15%; }
.wms-ops-dashboard-hero__floating--stock {
  right: 8%;
  bottom: 13%;
  border-color: color-mix(in oklab, var(--cyb-green) 48%, transparent);
}

.wms-ops-dashboard-hero__floating span,
.wms-ops-dashboard-hero__floating small {
  display: block;
  color: rgb(221 238 255 / 0.68);
  font-size: 0.57rem;
  font-weight: 750;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.wms-ops-dashboard-hero__floating strong {
  display: block;
  margin: 0.16rem 0;
  font-size: 1.55rem;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.wms-ops-dashboard-hero__pulse {
  position: absolute;
  z-index: 1;
  right: 40%;
  top: 50%;
  width: 5.7rem;
  aspect-ratio: 1;
  translate: 50% -50%;
  border: 1px solid color-mix(in oklab, var(--cyb-cyan) 55%, transparent);
  border-radius: 50%;
  box-shadow:
    0 0 36px color-mix(in oklab, var(--cyb-cyan) 30%, transparent),
    inset 0 0 20px color-mix(in oklab, var(--cyb-cyan) 24%, transparent);
}

.wms-ops-dashboard-hero__pulse span {
  position: absolute;
  inset: 18%;
  border: 1px solid color-mix(in oklab, var(--cyb-cyan) 45%, transparent);
  border-radius: 50%;
}

.wms-ops-dashboard-hero__pulse span:nth-child(2) { inset: 35%; }
.wms-ops-dashboard-hero__pulse span:nth-child(3) {
  inset: 47%;
  background: var(--cyb-cyan);
  box-shadow: 0 0 18px var(--cyb-cyan);
}

.wms-ops-dashboard-hero__clock {
  display: flex;
  min-width: min(100%, 15.5rem);
  flex-direction: column;
  align-items: flex-start;
  gap: 0.28rem;
  border: 1px solid color-mix(in oklab, var(--cyb-cyan) 32%, transparent);
  background: color-mix(in oklab, var(--cyb-nested) 88%, transparent);
  padding: 0.9rem 1rem;
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 0 100%);
  box-shadow:
    inset 0 0 22px color-mix(in oklab, var(--cyb-cyan) 8%, transparent),
    inset 0 0 0 1px color-mix(in oklab, var(--cyb-cyan) 10%, transparent);
}

.wms-ops-dashboard-hero__clock-label {
  font-size: 0.625rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: color-mix(in oklab, var(--cyb-cyan) 78%, hsl(var(--foreground)));
}

.wms-ops-dashboard-hero__clock-time {
  font-size: clamp(1.55rem, 2.6vw, 2.2rem);
  font-weight: 800;
  letter-spacing: 0.04em;
  line-height: 1.05;
  color: hsl(var(--foreground));
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 18px color-mix(in oklab, var(--cyb-cyan) 45%, transparent);
}

.wms-ops-dashboard-hero__clock-date {
  font-size: 0.72rem;
  line-height: 1.4;
  color: var(--cyb-text-dim);
  text-transform: capitalize;
}

.wms-ops-dashboard-hero__stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.65rem;
  min-width: min(100%, 18rem);
}

.wms-ops-dashboard-hero__stat {
  border: 1px solid color-mix(in oklab, var(--cyb-cyan) 30%, transparent);
  border-left: 3px solid var(--cyb-cyan);
  background: color-mix(in oklab, var(--cyb-nested) 88%, transparent);
  padding: 0.7rem 0.8rem;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%);
  box-shadow:
    inset 0 0 16px color-mix(in oklab, var(--cyb-cyan) 8%, transparent),
    inset 3px 0 12px -4px color-mix(in oklab, var(--cyb-cyan) 55%, transparent);
}

.wms-ops-dashboard-hero__stat:nth-child(2) {
  border-left-color: var(--cyb-magenta);
  box-shadow:
    inset 0 0 16px color-mix(in oklab, var(--cyb-magenta) 8%, transparent),
    inset 3px 0 12px -4px color-mix(in oklab, var(--cyb-magenta) 55%, transparent);
}

.wms-ops-dashboard-hero__stat-value {
  display: block;
  margin-top: 0.2rem;
  font-size: clamp(1.25rem, 2vw, 1.7rem);
  font-weight: 800;
  line-height: 1;
  color: hsl(var(--foreground));
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 12px color-mix(in oklab, var(--cyb-cyan) 35%, transparent);
}

.wms-ops-dashboard-hero__stat-hint {
  display: block;
  margin-top: 0.28rem;
  font-size: 0.62rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--cyb-text-dim);
}

@media (min-width: 1100px) {
  .wms-ops-dashboard-hero__main--with-clock:not(.wms-ops-dashboard-hero__main--pictorial),
  .wms-ops-dashboard-hero__main--with-stats:not(.wms-ops-dashboard-hero__main--pictorial) {
    flex-direction: row;
    align-items: stretch;
    justify-content: space-between;
    gap: 1.15rem;
  }

  .wms-ops-dashboard-hero__main--with-clock:not(.wms-ops-dashboard-hero__main--pictorial) .wms-ops-dashboard-hero__clock {
    justify-content: center;
  }
}

@media (max-width: 1099px) {
  .wms-ops-dashboard-hero__main--pictorial {
    grid-template-columns: minmax(16rem, 0.95fr) minmax(18rem, 1.2fr);
  }

  .wms-ops-dashboard-hero--pictorial .wms-ops-dashboard-hero__clock {
    grid-column: 1 / -1;
    min-height: auto;
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.55rem 1rem;
    border-inline-start: 0;
    border-top: 1px solid color-mix(in oklab, var(--cyb-cyan) 28%, transparent);
    padding: 0.85rem 1rem;
  }

  .wms-ops-dashboard-hero--pictorial .wms-ops-dashboard-hero__clock-time {
    margin: 0;
    font-size: 1.5rem;
  }
}

@media (max-width: 720px) {
  .wms-ops-dashboard-hero__main--pictorial {
    grid-template-columns: 1fr;
  }

  .wms-ops-dashboard-hero__visual {
    min-height: 12.5rem;
  }

  .wms-ops-dashboard-hero__visual::before {
    background: linear-gradient(180deg, var(--cyb-surface), transparent 30%, #07162e 100%);
  }

  .wms-ops-dashboard-hero__stats {
    grid-template-columns: 1fr;
  }
}

.wms-ops-dashboard-section--compact {
  min-height: 0;
}

.wms-ops-dashboard-analytics {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(16rem, 0.72fr);
  gap: 1.25rem;
}

.wms-ops-dashboard-section__link {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  color: var(--cyb-cyan);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.wms-ops-dashboard-error {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  border: 1px solid color-mix(in oklab, #ef4444 40%, transparent);
  border-left: 3px solid #ef4444;
  background: color-mix(in oklab, #ef4444 8%, var(--cyb-nested));
  padding: 0.75rem 0.9rem;
  color: #dc2626;
  font-size: 0.78rem;
  font-weight: 750;
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 0 100%);
}

.wms-ops-dashboard-error span { flex: 1; }
.wms-ops-dashboard-error button {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  border: 1px solid currentColor;
  padding: 0.38rem 0.6rem;
  font-weight: 850;
}

.wms-ops-dashboard-status--warn {
  border-color: color-mix(in oklab, var(--cyb-amber) 40%, transparent);
  border-left-color: var(--cyb-amber);
  box-shadow:
    inset 0 0 22px color-mix(in oklab, var(--cyb-amber) 8%, transparent),
    inset 3px 0 14px -4px color-mix(in oklab, var(--cyb-amber) 50%, transparent);
}

.wms-ops-dashboard-metric__value-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 0.4rem;
}

.wms-ops-dashboard-metric__sparkline {
  width: min(5.5rem, 42%);
  overflow: visible;
  color: var(--cyb-metric-tone);
  filter: drop-shadow(0 3px 5px color-mix(in oklab, var(--cyb-metric-tone) 30%, transparent));
}

.wms-ops-dashboard-metric--chart::after {
  display: none;
}

.wms-ops-dashboard-quick-grid--six {
  grid-template-columns: 1fr;
}

.wms-ops-dashboard-health {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid var(--cyb-line);
  background:
    linear-gradient(165deg, color-mix(in oklab, var(--cyb-cyan) 8%, var(--cyb-surface-2)) 0%, var(--cyb-surface) 45%, var(--cyb-nested) 100%);
  clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 14px 100%, 0 calc(100% - 14px));
  box-shadow:
    inset 0 0 0 1px color-mix(in oklab, var(--cyb-cyan) 10%, transparent),
    inset 0 0 46px color-mix(in oklab, var(--cyb-cyan) 5%, transparent);
}

.wms-ops-dashboard-health__item {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.55rem;
  border-inline-end: 1px solid color-mix(in oklab, var(--cyb-cyan) 16%, transparent);
  padding: 0.78rem 0.9rem;
  color: var(--cyb-text-dim);
}

.wms-ops-dashboard-health__item:last-child { border-inline-end: 0; }
.wms-ops-dashboard-health__item--success > svg { color: var(--cyb-green); }
.wms-ops-dashboard-health__item--warning > svg { color: var(--cyb-amber); }
.wms-ops-dashboard-health__item > span { display: grid; min-width: 0; }
.wms-ops-dashboard-health__item small {
  color: var(--cyb-text-dim);
  font-size: 0.51rem;
  font-weight: 750;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.wms-ops-dashboard-health__item strong {
  overflow: hidden;
  color: hsl(var(--foreground));
  font-size: 0.68rem;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.wms-ops-dashboard-health__item--warning strong { color: var(--cyb-amber); }

@media (min-width: 768px) {
  .wms-ops-dashboard-quick-grid--six {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1100px) {
  .wms-ops-dashboard-quick-grid--six {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (min-width: 1440px) {
  .wms-ops-dashboard-quick-grid--six {
    grid-template-columns: repeat(6, minmax(0, 1fr));
  }
}

@media (max-width: 1099px) {
  .wms-ops-dashboard-analytics {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .wms-ops-dashboard-hero__stats {
    grid-template-columns: 1fr;
  }

  .wms-ops-dashboard-health {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .wms-ops-dashboard-health__item:nth-child(2) { border-inline-end: 0; }
  .wms-ops-dashboard-health__item:nth-child(-n + 2) {
    border-bottom: 1px solid color-mix(in oklab, var(--cyb-cyan) 16%, transparent);
  }
}

@media (max-width: 460px) {
  .wms-ops-dashboard-health {
    grid-template-columns: 1fr;
  }

  .wms-ops-dashboard-health__item {
    border-inline-end: 0;
    border-bottom: 1px solid color-mix(in oklab, var(--cyb-cyan) 16%, transparent);
  }

  .wms-ops-dashboard-health__item:last-child { border-bottom: 0; }
}

.wms-ops-dashboard-status {
  position: relative;
  border: 1px solid color-mix(in oklab, var(--cyb-green) 30%, transparent);
  border-left: 3px solid var(--cyb-green);
  background: color-mix(in oklab, var(--cyb-nested) 90%, transparent);
  padding: 0.8rem 1rem;
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 0 100%);
  box-shadow:
    inset 0 0 22px color-mix(in oklab, var(--cyb-green) 7%, transparent),
    inset 3px 0 14px -4px color-mix(in oklab, var(--cyb-green) 50%, transparent);
}

.wms-ops-dashboard-status__line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.2rem;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.wms-ops-dashboard-status__prompt {
  color: var(--cyb-green);
  text-shadow: 0 0 10px color-mix(in oklab, var(--cyb-green) 70%, transparent);
}

.wms-ops-dashboard-status__ready {
  color: var(--cyb-green);
  text-shadow: 0 0 12px color-mix(in oklab, var(--cyb-green) 65%, transparent);
}

.wms-ops-dashboard-status__label {
  color: hsl(var(--foreground));
}

.wms-ops-dashboard-status__sep {
  color: color-mix(in oklab, var(--cyb-cyan) 55%, transparent);
}

.wms-ops-dashboard-status__cursor {
  display: inline-block;
  margin-left: 0.1rem;
  animation: wms-ops-dashboard-cursor-blink 1.1s step-end infinite;
}

.wms-ops-dashboard-status__hint {
  margin-top: 0.35rem;
  font-size: 0.75rem;
  line-height: 1.45;
  color: color-mix(in oklab, hsl(var(--foreground)) 58%, transparent);
}

@keyframes wms-ops-dashboard-cursor-blink {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

.wms-ops-dashboard-metrics {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

@media (min-width: 768px) {
  .wms-ops-dashboard-metrics {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (min-width: 1280px) {
  .wms-ops-dashboard-metrics {
    grid-template-columns: repeat(6, minmax(0, 1fr));
  }
}

.wms-ops-dashboard-page .wms-ops-dashboard-metric {
  --cyb-metric-tone: var(--cyb-cyan);
  padding: 0.85rem 0.9rem 0.95rem;
  border-color: color-mix(in oklab, var(--cyb-metric-tone) 36%, transparent);
  transition: box-shadow 180ms ease, border-color 180ms ease, transform 180ms ease;
}

.wms-ops-dashboard-page .wms-ops-dashboard-metric::before {
  background: linear-gradient(90deg, var(--cyb-metric-tone) 0%, transparent 85%);
  box-shadow: 0 0 14px color-mix(in oklab, var(--cyb-metric-tone) 60%, transparent);
}

/* vertical data ticks on metric right side */
.wms-ops-dashboard-metric::after {
  content: '';
  pointer-events: none;
  position: absolute;
  top: 0.6rem;
  bottom: 0.6rem;
  right: 0.45rem;
  width: 3px;
  background: repeating-linear-gradient(
    180deg,
    color-mix(in oklab, var(--cyb-metric-tone) 55%, transparent) 0 4px,
    transparent 4px 9px
  );
  opacity: 0.7;
}

.wms-ops-dashboard-metric:hover {
  border-color: color-mix(in oklab, var(--cyb-metric-tone) 75%, transparent);
  box-shadow:
    inset 0 0 0 1px color-mix(in oklab, var(--cyb-metric-tone) 22%, transparent),
    inset 0 0 34px color-mix(in oklab, var(--cyb-metric-tone) 12%, transparent);
  transform: translateY(-2px);
}

.wms-ops-dashboard-metric--accent { --cyb-metric-tone: var(--cyb-magenta); }
.wms-ops-dashboard-metric--warn { --cyb-metric-tone: var(--cyb-amber); }
.wms-ops-dashboard-metric--success { --cyb-metric-tone: var(--cyb-green); }

.wms-ops-dashboard-metric .wms-ops-dashboard-metric__label {
  color: color-mix(in oklab, var(--cyb-metric-tone) 82%, hsl(var(--foreground)));
}

.wms-ops-dashboard-metric__value {
  margin-top: 0.4rem;
  font-size: clamp(1.5rem, 2.4vw, 2.1rem);
  font-weight: 800;
  line-height: 1.05;
  color: hsl(var(--foreground));
  text-shadow: 0 0 18px color-mix(in oklab, var(--cyb-metric-tone) 55%, transparent);
}

.wms-ops-dashboard-metric__hint {
  margin-top: 0.4rem;
  font-size: 0.6875rem;
  line-height: 1.35;
  color: var(--cyb-text-dim);
}

.wms-ops-dashboard-section {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding: 1rem 1.1rem 1.1rem;
  min-height: 18rem;
}

.wms-ops-dashboard-section__body {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
}

.wms-ops-dashboard-section__header {
  position: relative;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.9rem;
  padding-bottom: 0.7rem;
  border-bottom: 1px solid color-mix(in oklab, var(--cyb-cyan) 22%, transparent);
}

.wms-ops-dashboard-section__header .wms-ops-pt-terminal__title {
  text-shadow: 0 0 12px color-mix(in oklab, var(--cyb-cyan) 45%, transparent);
}

.wms-ops-dashboard-section__meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.25rem;
  text-align: right;
}

.wms-ops-dashboard-section .wms-ops-code-badge {
  border-color: color-mix(in oklab, var(--cyb-magenta) 55%, transparent);
  color: var(--cyb-magenta);
  text-shadow: 0 0 10px color-mix(in oklab, var(--cyb-magenta) 55%, transparent);
  box-shadow:
    inset 0 0 12px color-mix(in oklab, var(--cyb-magenta) 10%, transparent),
    0 0 10px color-mix(in oklab, var(--cyb-magenta) 22%, transparent);
}

.wms-ops-dashboard-activity-panel {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  border: 1px solid color-mix(in oklab, var(--cyb-cyan) 20%, transparent);
  background: color-mix(in oklab, var(--cyb-nested) 92%, transparent);
  padding: 0.65rem;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 10px 100%, 0 calc(100% - 10px));
  box-shadow: inset 0 0 28px color-mix(in oklab, var(--cyb-cyan) 6%, transparent);
}

.wms-ops-dashboard-activity {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding-right: 0.35rem;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklab, var(--cyb-cyan) 70%, transparent) transparent;
}

.wms-ops-dashboard-activity::-webkit-scrollbar {
  width: 8px;
}

.wms-ops-dashboard-activity::-webkit-scrollbar-track {
  background: color-mix(in oklab, var(--cyb-nested) 80%, transparent);
  border-left: 1px solid color-mix(in oklab, var(--cyb-cyan) 22%, transparent);
}

.wms-ops-dashboard-activity::-webkit-scrollbar-thumb {
  border-radius: 0;
  border: 1px solid color-mix(in oklab, var(--cyb-cyan) 55%, transparent);
  background: linear-gradient(180deg, color-mix(in oklab, var(--cyb-cyan) 60%, #0b1220), color-mix(in oklab, var(--cyb-magenta) 45%, #0b1220));
}

.wms-ops-dashboard-activity::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(180deg, var(--cyb-cyan), color-mix(in oklab, var(--cyb-magenta) 80%, transparent));
  box-shadow: 0 0 10px color-mix(in oklab, var(--cyb-cyan) 45%, transparent);
}

.wms-ops-dashboard-activity__row {
  display: flex;
  gap: 0.75rem;
  padding: 0.7rem 0.75rem 0.7rem 0.85rem;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 10px 100%, 0 calc(100% - 10px));
  color: inherit;
  text-decoration: none;
  transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

.wms-ops-dashboard-activity__row::before {
  opacity: 0.45;
}

.wms-ops-dashboard-activity__row:hover {
  border-color: color-mix(in oklab, var(--cyb-cyan) 65%, transparent);
  box-shadow: inset 0 0 26px color-mix(in oklab, var(--cyb-cyan) 10%, transparent);
  transform: translateX(3px);
}

.wms-ops-dashboard-activity__rail {
  width: 3px;
  flex-shrink: 0;
  background: linear-gradient(
    180deg,
    var(--cyb-cyan),
    color-mix(in oklab, var(--cyb-magenta) 80%, transparent)
  );
  box-shadow: 0 0 12px color-mix(in oklab, var(--cyb-cyan) 55%, transparent);
}

.wms-ops-dashboard-activity__title {
  margin-top: 0.35rem;
  font-size: 0.875rem;
  font-weight: 700;
  color: hsl(var(--foreground));
  text-shadow: 0 0 10px color-mix(in oklab, var(--cyb-cyan) 25%, transparent);
}

.wms-ops-dashboard-activity__subtitle,
.wms-ops-dashboard-activity__time,
.wms-ops-dashboard-activity__empty {
  font-size: 0.75rem;
  line-height: 1.4;
  color: var(--cyb-text-dim);
}

.wms-ops-dashboard-activity__time {
  margin-top: 0.2rem;
  font-size: 0.6875rem;
  color: color-mix(in oklab, var(--cyb-cyan) 60%, var(--cyb-text-dim));
}

.wms-ops-dashboard-quick-grid {
  display: grid;
  gap: 0.75rem;
  border: 1px solid color-mix(in oklab, var(--cyb-cyan) 20%, transparent);
  background: color-mix(in oklab, var(--cyb-nested) 92%, transparent);
  padding: 0.65rem;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 10px 100%, 0 calc(100% - 10px));
  box-shadow: inset 0 0 28px color-mix(in oklab, var(--cyb-cyan) 6%, transparent);
}

.wms-ops-dashboard-module {
  display: block;
  overflow: hidden;
  padding: 0.85rem 0.9rem;
  transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

.wms-ops-dashboard-module:hover,
.wms-ops-dashboard-module:focus-visible {
  border-color: color-mix(in oklab, var(--cyb-cyan) 80%, transparent);
  box-shadow:
    inset 0 0 0 1px color-mix(in oklab, var(--cyb-cyan) 25%, transparent),
    inset 0 0 34px color-mix(in oklab, var(--cyb-cyan) 12%, transparent);
  transform: translateY(-2px);
}

.wms-ops-dashboard-module__scan {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 0%, color-mix(in oklab, var(--cyb-cyan) 16%, transparent) 50%, transparent 100%);
  transform: translateY(-120%);
  opacity: 0;
  transition: transform 700ms ease, opacity 700ms ease;
}

.wms-ops-dashboard-module:hover .wms-ops-dashboard-module__scan,
.wms-ops-dashboard-module:focus-visible .wms-ops-dashboard-module__scan {
  transform: translateY(120%);
  opacity: 1;
}

.wms-ops-dashboard-module__head,
.wms-ops-dashboard-module__body,
.wms-ops-dashboard-module__action {
  position: relative;
  z-index: 1;
}

.wms-ops-dashboard-module__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.wms-ops-dashboard-module__index {
  font-size: 0.75rem;
  font-weight: 800;
  color: var(--cyb-magenta);
  text-shadow: 0 0 10px color-mix(in oklab, var(--cyb-magenta) 55%, transparent);
}

.wms-ops-dashboard-module__body {
  display: flex;
  align-items: flex-start;
  gap: 0.7rem;
  margin-top: 0.7rem;
}

.wms-ops-dashboard-module__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.25rem;
  height: 2.25rem;
  flex-shrink: 0;
  border: 1px solid color-mix(in oklab, var(--cyb-cyan) 45%, transparent);
  background: color-mix(in oklab, var(--cyb-cyan) 8%, var(--cyb-nested));
  color: var(--cyb-cyan);
  clip-path: polygon(0 0, calc(100% - 7px) 0, 100% 7px, 100% 100%, 7px 100%, 0 calc(100% - 7px));
  box-shadow: inset 0 0 14px color-mix(in oklab, var(--cyb-cyan) 16%, transparent);
  filter: drop-shadow(0 0 6px color-mix(in oklab, var(--cyb-cyan) 40%, transparent));
  transition: color 160ms ease, background-color 160ms ease;
}

.wms-ops-dashboard-module:hover .wms-ops-dashboard-module__icon {
  color: color-mix(in oklab, var(--cyb-cyan) 40%, white);
}

.wms-ops-dashboard-module__title {
  font-size: 0.8125rem;
  font-weight: 700;
  color: hsl(var(--foreground));
  text-shadow: 0 0 10px color-mix(in oklab, var(--cyb-cyan) 25%, transparent);
}

.wms-ops-dashboard-module__desc {
  margin-top: 0.15rem;
  font-size: 0.6875rem;
  line-height: 1.35;
  color: var(--cyb-text-dim);
}

.wms-ops-dashboard-module__action {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 0.75rem;
  padding-top: 0.55rem;
  border-top: 1px dashed color-mix(in oklab, var(--cyb-cyan) 28%, transparent);
  font-size: 0.6875rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--cyb-cyan);
  text-shadow: 0 0 10px color-mix(in oklab, var(--cyb-cyan) 50%, transparent);
}

/* Process hubs (goods receipt, shipping, transfer, …) — module-launch surfaces */
.wms-ops-process-hub .wms-ops-dashboard-section {
  min-height: 0;
}

/* Process parameters hub — vertical tabs + live settings panel */
.wms-ops-process-params-hub {
  display: grid;
  grid-template-columns: minmax(15rem, 18rem) minmax(0, 1fr);
  gap: 0.9rem;
  align-items: start;
  min-height: min(72vh, 52rem);
}

.wms-ops-process-params-hub__rail {
  position: sticky;
  top: 0.35rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  max-height: calc(100dvh - 7.5rem);
  padding: 0.85rem 0.75rem;
  border: 1px solid color-mix(in oklab, var(--wms-brand-primary) 22%, var(--wms-app-border));
  border-radius: 1rem;
  background:
    linear-gradient(
      165deg,
      color-mix(in oklab, var(--wms-brand-primary) 8%, var(--wms-app-panel)) 0%,
      var(--wms-app-panel) 48%,
      color-mix(in oklab, var(--wms-app-panel) 92%, transparent) 100%
    );
  box-shadow: 0 10px 28px -18px color-mix(in oklab, var(--wms-brand-primary) 35%, transparent);
  overflow: hidden;
}

.wms-ops-process-params-hub__rail-head {
  padding: 0 0.25rem 0.55rem;
  border-bottom: 1px solid color-mix(in oklab, var(--wms-brand-primary) 16%, var(--wms-app-border));
}

.wms-ops-process-params-hub__eyebrow {
  margin: 0;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--wms-brand-primary);
}

.wms-ops-process-params-hub__title {
  margin: 0.28rem 0 0;
  font-size: 1rem;
  font-weight: 750;
  line-height: 1.25;
  color: var(--wms-app-text);
}

.wms-ops-process-params-hub__subtitle {
  margin: 0.35rem 0 0;
  font-size: 0.72rem;
  line-height: 1.4;
  color: var(--wms-app-text-muted);
}

.wms-ops-process-params-hub__tabs {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  min-height: 0;
  overflow: auto;
  padding-right: 0.15rem;
}

.wms-ops-process-params-hub__tab {
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  width: 100%;
  padding: 0.55rem 0.55rem;
  border: 1px solid transparent;
  border-radius: 0.7rem;
  color: var(--wms-app-text-muted);
  text-decoration: none;
  transition:
    background-color 150ms ease,
    border-color 150ms ease,
    color 150ms ease,
    box-shadow 150ms ease;
}

.wms-ops-process-params-hub__tab:hover {
  color: var(--wms-app-text);
  background: color-mix(in oklab, var(--wms-brand-primary) 8%, transparent);
  border-color: color-mix(in oklab, var(--wms-brand-primary) 14%, transparent);
}

.wms-ops-process-params-hub__tab--active {
  color: var(--wms-brand-primary);
  background: color-mix(in oklab, var(--wms-brand-primary) 12%, transparent);
  border-color: color-mix(in oklab, var(--wms-brand-primary) 28%, transparent);
  box-shadow: inset 3px 0 0 var(--wms-brand-primary);
}

.wms-ops-process-params-hub__tab-icon {
