/* Welcome ? cyberpunk terminal boot card */
.wms-ops-welcome-page {
  --cyb-surface: #0a1020;
  --cyb-surface-2: #0e1730;
  --cyb-nested: #060b16;
  --cyb-cyan: #41e8ff;
  --cyb-magenta: #ff6a3d;
  --cyb-green: #43ffa4;
  --cyb-text-dim: color-mix(in oklab, #dff5ff 58%, transparent);
  display: flex;
  min-height: 60vh;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

html:not(.dark) .wms-ops-welcome-page {
  --cyb-surface: #f2f6fc;
  --cyb-surface-2: #fbfdff;
  --cyb-nested: #e4ecf6;
  --cyb-cyan: #0e7490;
  --cyb-magenta: #c2410c;
  --cyb-green: #15803d;
  --cyb-text-dim: color-mix(in oklab, #0f172a 62%, transparent);
}

.wms-ops-welcome-card {
  position: relative;
  width: 100%;
  max-width: 34rem;
  overflow: hidden;
  animation: cyb-welcome-glitch 10s steps(1, end) infinite;
  border: 1px solid color-mix(in oklab, var(--cyb-cyan) 36%, transparent);
  background:
    radial-gradient(circle at 12% -10%, color-mix(in oklab, var(--cyb-cyan) 18%, transparent), transparent 46%),
    radial-gradient(circle at 90% 115%, color-mix(in oklab, var(--cyb-magenta) 14%, transparent), transparent 42%),
    linear-gradient(165deg, color-mix(in oklab, var(--cyb-cyan) 8%, var(--cyb-surface-2)) 0%, var(--cyb-surface) 45%, var(--cyb-nested) 100%);
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 16px 100%, 0 calc(100% - 16px));
  padding: 1.75rem 1.85rem 1.85rem;
  box-shadow:
    inset 0 0 0 1px color-mix(in oklab, var(--cyb-cyan) 10%, transparent),
    inset 0 0 52px color-mix(in oklab, var(--cyb-cyan) 7%, transparent);
}

.wms-ops-welcome-card::before {
  content: '';
  pointer-events: none;
  position: absolute;
  top: 0;
  left: 0;
  right: 16px;
  height: 2px;
  z-index: 2;
  background: linear-gradient(90deg, var(--cyb-cyan) 0%, color-mix(in oklab, var(--cyb-magenta) 85%, transparent) 55%, transparent 90%);
  box-shadow: 0 0 14px color-mix(in oklab, var(--cyb-cyan) 60%, transparent);
}

.wms-ops-welcome-card::after {
  content: '';
  pointer-events: none;
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    180deg,
    transparent 0,
    transparent 3px,
    color-mix(in oklab, var(--cyb-cyan) 4%, transparent) 3px,
    color-mix(in oklab, var(--cyb-cyan) 4%, transparent) 4px
  );
  opacity: 0.5;
}

.wms-ops-welcome-card__frame {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 1;
}

.wms-ops-welcome-card__corner {
  position: absolute;
  width: 1.1rem;
  height: 1.1rem;
  border-color: var(--cyb-cyan);
  filter: drop-shadow(0 0 5px color-mix(in oklab, var(--cyb-cyan) 70%, transparent));
}

.wms-ops-welcome-card__corner--tl { top: 0; left: 0; border-top: 2px solid; border-left: 2px solid; }
.wms-ops-welcome-card__corner--tr { top: 0; right: 0; border-top: 2px solid; border-right: 2px solid; border-color: var(--cyb-magenta); }
.wms-ops-welcome-card__corner--bl { bottom: 0; left: 0; border-bottom: 2px solid; border-left: 2px solid; border-color: var(--cyb-magenta); }
.wms-ops-welcome-card__corner--br { bottom: 0; right: 0; border-bottom: 2px solid; border-right: 2px solid; }

.wms-ops-welcome-card__content {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.wms-ops-welcome-card__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--cyb-cyan);
  text-shadow: 0 0 12px color-mix(in oklab, var(--cyb-cyan) 60%, transparent);
}

.wms-ops-welcome-card__eyebrow::before,
.wms-ops-welcome-card__eyebrow::after {
  content: '';
  width: 0.45rem;
  height: 0.45rem;
  background: var(--cyb-cyan);
  clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%);
  box-shadow: 0 0 10px var(--cyb-cyan);
  animation: cyb-glow-pulse 2.4s ease-in-out infinite;
}

.wms-ops-welcome-card__title {
  margin-top: 0.7rem;
  font-size: clamp(1.5rem, 3vw, 2.1rem);
  font-weight: 800;
  line-height: 1.12;
  color: hsl(var(--foreground));
  text-shadow:
    0 0 22px color-mix(in oklab, var(--cyb-cyan) 45%, transparent),
    2px 0 0 color-mix(in oklab, var(--cyb-magenta) 32%, transparent),
    -2px 0 0 color-mix(in oklab, var(--cyb-cyan) 32%, transparent);
}

.wms-ops-welcome-card__status {
  margin-top: 0.65rem;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--cyb-green);
  text-shadow: 0 0 12px color-mix(in oklab, var(--cyb-green) 60%, transparent);
}

.wms-ops-welcome-card__cursor {
  display: inline-block;
  margin-left: 0.15rem;
  animation: wms-ops-dashboard-cursor-blink 1.1s step-end infinite;
}

.wms-ops-welcome-card__subtitle {
  margin-top: 0.85rem;
  max-width: 26rem;
  font-size: 0.8125rem;
  line-height: 1.55;
  color: var(--cyb-text-dim);
}

.wms-ops-welcome-card__cta {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 1.35rem;
  padding: 0.7rem 1.5rem;
  border: 1px solid color-mix(in oklab, var(--cyb-cyan) 55%, transparent);
  background: color-mix(in oklab, var(--cyb-cyan) 10%, var(--cyb-nested));
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 10px 100%, 0 calc(100% - 10px));
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--cyb-cyan);
  text-shadow: 0 0 10px color-mix(in oklab, var(--cyb-cyan) 50%, transparent);
  box-shadow: inset 0 0 18px color-mix(in oklab, var(--cyb-cyan) 12%, transparent);
  transition: border-color 160ms ease, box-shadow 160ms ease, color 160ms ease, transform 160ms ease;
}

.wms-ops-welcome-card__cta:hover,
.wms-ops-welcome-card__cta:focus-visible {
  border-color: var(--cyb-cyan);
  color: color-mix(in oklab, var(--cyb-cyan) 40%, white);
  box-shadow:
    inset 0 0 26px color-mix(in oklab, var(--cyb-cyan) 20%, transparent),
    0 0 18px color-mix(in oklab, var(--cyb-cyan) 25%, transparent);
  transform: translateY(-1px);
}

/* electric glitch burst: quiet for ~9.4s, then rapid jitter + color rip */
@keyframes cyb-welcome-glitch {
  0%, 93.9% {
    transform: none;
    filter: none;
  }
  94% {
    transform: translate(-3px, 1px) skewX(-2deg);
    filter: hue-rotate(-35deg) saturate(2) brightness(1.25);
  }
  94.6% {
    transform: translate(4px, -2px) skewX(1.5deg);
    filter: hue-rotate(25deg) saturate(1.6) contrast(1.3);
    opacity: 0.82;
  }
  95.2% {
    transform: translate(-2px, 2px);
    filter: none;
    opacity: 1;
  }
  95.8% {
    transform: translate(2px, -1px) skewX(-1deg);
    filter: hue-rotate(-20deg) brightness(1.35);
  }
  96.4% {
    transform: translate(-4px, 0) skewX(2.5deg);
    filter: invert(0.08) saturate(2.2);
    opacity: 0.9;
  }
  97% {
    transform: translate(1px, 1px);
    filter: hue-rotate(15deg) brightness(1.15);
  }
  97.6%, 100% {
    transform: none;
    filter: none;
    opacity: 1;
  }
}

/* title gets an extra chromatic rip during the same burst window */
.wms-ops-welcome-card__title {
  animation: cyb-welcome-title-glitch 10s steps(1, end) infinite;
}

@keyframes cyb-welcome-title-glitch {
  0%, 93.9%, 97.6%, 100% {
    transform: none;
  }
  94% {
    transform: translateX(3px);
    text-shadow:
      -4px 0 0 color-mix(in oklab, var(--cyb-cyan) 85%, transparent),
      4px 0 0 color-mix(in oklab, var(--cyb-magenta) 85%, transparent);
  }
  95.2% {
    transform: translateX(-3px);
    text-shadow:
      4px 0 0 color-mix(in oklab, var(--cyb-cyan) 85%, transparent),
      -4px 0 0 color-mix(in oklab, var(--cyb-magenta) 85%, transparent);
  }
  96.4% {
    transform: translateX(2px) skewX(-3deg);
    text-shadow:
      -3px 1px 0 color-mix(in oklab, var(--cyb-cyan) 85%, transparent),
      3px -1px 0 color-mix(in oklab, var(--cyb-magenta) 85%, transparent);
  }
}

@media (prefers-reduced-motion: reduce) {
  .wms-ops-welcome-card,
  .wms-ops-welcome-card__title {
    animation: none;
  }
}

html:not(.dark) .wms-ops-welcome-card__title {
