/* ?? Profile theme grid scrollbar ?? */
.wms-ops-profile-modal__theme-grid {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklab, var(--wms-brand-primary) 52%, #64748b) color-mix(in oklab, #07080e 92%, transparent);
}

.wms-ops-profile-modal__theme-grid::-webkit-scrollbar {
  width: 8px;
}

.wms-ops-profile-modal__theme-grid::-webkit-scrollbar-track {
  background: color-mix(in oklab, #07080e 92%, transparent);
  border-left: 1px solid color-mix(in oklab, var(--wms-brand-primary) 12%, transparent);
}

.wms-ops-profile-modal__theme-grid::-webkit-scrollbar-thumb {
  border-radius: 0;
  border: 1px solid color-mix(in oklab, var(--wms-brand-primary) 38%, transparent);
  background: color-mix(in oklab, var(--wms-brand-primary) 34%, #334155);
  transition: background-color 180ms ease, box-shadow 180ms ease;
}

.wms-ops-profile-modal__theme-grid::-webkit-scrollbar-thumb:hover {
  background: color-mix(in oklab, var(--wms-brand-primary) 58%, #334155);
