}

html:not(.dark) .wms-ops-profile-modal__theme-grid::-webkit-scrollbar-track {
  background: color-mix(in oklab, #f1f5f9 92%, transparent);
}

/* ?? Profile theme terminal checkbox ?? */
.wms-ops-profile-theme-check {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 1.125rem;
  height: 1.125rem;
  border: 1px solid color-mix(in oklab, var(--wms-brand-primary) 38%, #64748b);
  background: color-mix(in oklab, #07080e 92%, transparent);
  box-shadow:
    inset 0 0 0 1px color-mix(in oklab, var(--wms-brand-primary) 6%, transparent),
    0 0 6px color-mix(in oklab, var(--wms-brand-primary) 8%, transparent);
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    background 160ms ease;
}

.wms-ops-profile-modal__theme-option:hover .wms-ops-profile-theme-check {
  border-color: color-mix(in oklab, var(--wms-brand-primary) 62%, white);
  box-shadow:
    inset 0 0 0 1px color-mix(in oklab, var(--wms-brand-primary) 12%, transparent),
    0 0 10px color-mix(in oklab, var(--wms-brand-primary) 18%, transparent);
}

.wms-ops-profile-theme-check__fill {
  position: absolute;
  inset: 2px;
  opacity: 0;
  transform: scale(0.55);
  background: radial-gradient(
    circle at 50% 50%,
    color-mix(in oklab, var(--wms-brand-primary) 88%, white) 0%,
    color-mix(in oklab, var(--wms-brand-primary) 52%, transparent) 58%,
    transparent 100%
  );
  box-shadow:
    inset 0 0 6px color-mix(in oklab, var(--wms-brand-primary) 72%, white),
    inset 0 0 14px color-mix(in oklab, var(--wms-brand-primary) 48%, transparent);
  transition:
    opacity 160ms ease,
    transform 160ms ease,
    box-shadow 160ms ease;
  pointer-events: none;
}

.wms-ops-profile-theme-check--on {
  border-color: color-mix(in oklab, var(--wms-brand-primary) 82%, white);
  background: color-mix(in oklab, var(--wms-brand-primary) 10%, #07080e);
  box-shadow:
    inset 0 0 0 1px color-mix(in oklab, var(--wms-brand-primary) 28%, transparent),
    0 0 16px color-mix(in oklab, var(--wms-brand-primary) 42%, transparent),
    0 0 28px color-mix(in oklab, var(--wms-brand-primary) 18%, transparent);
}

.wms-ops-profile-theme-check--on .wms-ops-profile-theme-check__fill {
  opacity: 1;
  transform: scale(1);
  box-shadow:
    inset 0 0 8px color-mix(in oklab, var(--wms-brand-primary) 92%, white),
    inset 0 0 18px color-mix(in oklab, var(--wms-brand-primary) 62%, transparent),
    0 0 10px color-mix(in oklab, var(--wms-brand-primary) 55%, transparent);
}

.wms-ops-profile-theme-check__corner {
  position: absolute;
  width: 0.3rem;
  height: 0.3rem;
  border-color: color-mix(in oklab, var(--wms-brand-primary) 58%, transparent);
  opacity: 0.75;
  transition: border-color 160ms ease, opacity 160ms ease, filter 160ms ease;
}

.wms-ops-profile-theme-check--on .wms-ops-profile-theme-check__corner {
  border-color: color-mix(in oklab, var(--wms-brand-primary) 92%, white);
  opacity: 1;
  filter: drop-shadow(0 0 3px color-mix(in oklab, var(--wms-brand-primary) 65%, transparent));
}

.wms-ops-profile-theme-check__corner--tl {
  top: -1px;
  left: -1px;
  border-top: 1px solid;
  border-left: 1px solid;
}

.wms-ops-profile-theme-check__corner--tr {
  top: -1px;
  right: -1px;
  border-top: 1px solid;
  border-right: 1px solid;
}

.wms-ops-profile-theme-check__corner--bl {
  bottom: -1px;
  left: -1px;
  border-bottom: 1px solid;
  border-left: 1px solid;
}

.wms-ops-profile-theme-check__corner--br {
  bottom: -1px;
  right: -1px;
  border-bottom: 1px solid;
  border-right: 1px solid;
}

.wms-ops-profile-modal__theme-option--selected {
  box-shadow:
    inset 0 0 0 1px color-mix(in oklab, var(--wms-brand-primary) 22%, transparent),
    0 0 18px color-mix(in oklab, var(--wms-brand-primary) 14%, transparent) !important;
}

/* Profile page ? terminal card */
.wms-ops-profile-page {
  --cyb-surface: #0a1020;
  --cyb-surface-2: #0e1730;
  --cyb-nested: #060b16;
  --cyb-cyan: #41e8ff;
  --cyb-magenta: #ff6a3d;
  --cyb-text-dim: color-mix(in oklab, #dff5ff 58%, transparent);
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

html:not(.dark) .wms-ops-profile-page {
  --cyb-surface: #f2f6fc;
  --cyb-surface-2: #fbfdff;
  --cyb-nested: #e4ecf6;
  --cyb-cyan: #0e7490;
  --cyb-magenta: #c2410c;
  --cyb-text-dim: color-mix(in oklab, #0f172a 62%, transparent);
}

.wms-ops-profile-page__card {
  position: relative;
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--cyb-cyan) 36%, transparent);
  background:
    radial-gradient(circle at 12% -10%, color-mix(in oklab, var(--cyb-cyan) 16%, transparent), transparent 46%),
    linear-gradient(165deg, color-mix(in oklab, var(--cyb-cyan) 8%, var(--cyb-surface-2)) 0%, var(--cyb-surface) 48%, var(--cyb-nested) 100%);
  clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 18px 100%, 0 calc(100% - 18px));
  padding: 1.5rem 1.5rem 1.75rem;
  box-shadow:
    inset 0 0 0 1px color-mix(in oklab, var(--cyb-cyan) 10%, transparent),
    inset 0 0 40px color-mix(in oklab, var(--cyb-cyan) 6%, transparent);
}

.wms-ops-profile-page__card::before {
  content: '';
