  --wms-app-aura-start: color-mix(in oklab, var(--wms-brand-primary) 7%, transparent);
  --wms-app-aura-end: color-mix(in oklab, var(--wms-brand-accent) 6%, transparent);
}

/* ?? Ambient: silik m?hendislik ?zgaras? + yumu?ak glow ?? */
