.wms-premium-loading__message {
  font-family: var(--wms-premium-font);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-align: center;
  color: color-mix(in oklab, var(--wms-brand-primary) 45%, hsl(var(--foreground)));
  animation: wms-premium-loading-fade 1.8s ease-in-out infinite;
}

/* Premium full-page / route-transition loader */
.wms-premium-route-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.95rem;
  width: 100%;
  max-width: 20rem;
  margin-inline: auto;
  padding: 1.1rem 1.15rem 1.2rem;
  border: 1px solid color-mix(in oklab, var(--wms-brand-primary) 18%, hsl(var(--border)));
  border-radius: 1.15rem;
  background:
    radial-gradient(
      circle at 50% 18%,
      color-mix(in oklab, var(--wms-brand-primary) 16%, transparent),
      transparent 58%
    ),
    linear-gradient(
      180deg,
      color-mix(in oklab, var(--wms-brand-primary) 6%, hsl(var(--card))) 0%,
      hsl(var(--card)) 100%
    );
  box-shadow:
    0 18px 40px -24px var(--wms-brand-shadow),
    inset 0 1px 0 color-mix(in oklab, white 8%, transparent);
}

.wms-premium-route-loading__stage {
  position: relative;
  display: grid;
  place-items: center;
  width: 4.5rem;
  height: 4.5rem;
}

.wms-premium-route-loading__glow {
  position: absolute;
  inset: 12%;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    color-mix(in oklab, var(--wms-brand-primary) 35%, transparent) 0%,
    transparent 70%
  );
  filter: blur(8px);
  animation: wms-premium-loading-glow 2.2s ease-in-out infinite;
}

.wms-premium-route-loading__orbit {
  position: relative;
  width: 3.35rem;
  height: 3.35rem;
}

.wms-premium-route-loading__ring {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2px solid transparent;
}

.wms-premium-route-loading__ring--outer {
  border-top-color: var(--wms-brand-primary);
  border-right-color: color-mix(in oklab, var(--wms-brand-accent) 65%, var(--wms-brand-primary));
  box-shadow: 0 0 16px -2px var(--wms-brand-shadow);
  animation: wms-premium-loading-spin 1.05s cubic-bezier(0.45, 0.05, 0.55, 0.95) infinite;
}

.wms-premium-route-loading__ring--mid {
  inset: 12%;
  border-bottom-color: color-mix(in oklab, var(--wms-brand-accent) 80%, transparent);
  border-left-color: color-mix(in oklab, var(--wms-brand-primary) 45%, transparent);
  animation: wms-premium-loading-spin-rev 1.55s linear infinite;
  opacity: 0.85;
}

.wms-premium-route-loading__ring--inner {
  inset: 28%;
  border-top-color: color-mix(in oklab, var(--wms-brand-primary) 55%, transparent);
  animation: wms-premium-loading-spin 0.85s linear infinite;
  opacity: 0.7;
}

.wms-premium-route-loading__core {
  position: absolute;
  inset: 38%;
  border-radius: 50%;
  background: linear-gradient(
    135deg,
    color-mix(in oklab, var(--wms-brand-primary) 70%, transparent),
    color-mix(in oklab, var(--wms-brand-accent) 45%, transparent)
  );
  box-shadow: 0 0 14px -1px var(--wms-brand-shadow);
  animation: wms-premium-loading-pulse 1.6s ease-in-out infinite;
}

.wms-premium-route-loading__spark {
  position: absolute;
  top: 2%;
  left: 48%;
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 50%;
  background: color-mix(in oklab, white 70%, var(--wms-brand-accent));
  box-shadow: 0 0 10px color-mix(in oklab, var(--wms-brand-primary) 70%, transparent);
  transform-origin: 50% 1.55rem;
  animation: wms-premium-loading-spin 1.05s linear infinite;
}

.wms-premium-route-loading__copy {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.35rem;
  text-align: center;
}

.wms-premium-route-loading__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-family: var(--wms-premium-font);
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: color-mix(in oklab, var(--wms-brand-primary) 55%, hsl(var(--muted-foreground)));
}

.wms-premium-route-loading__code {
  padding: 0.12rem 0.4rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--wms-brand-primary) 12%, transparent);
  color: var(--wms-brand-primary);
}

.wms-premium-route-loading__pulse-dot {
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 50%;
  background: var(--wms-brand-accent);
  box-shadow: 0 0 8px color-mix(in oklab, var(--wms-brand-accent) 60%, transparent);
  animation: wms-premium-loading-fade 1.2s ease-in-out infinite;
}

.wms-premium-route-loading__step-label {
  opacity: 0.9;
}

.wms-premium-route-loading__message {
  font-family: var(--wms-premium-font);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  text-align: center;
  color: color-mix(in oklab, var(--wms-brand-primary) 28%, hsl(var(--foreground)));
  animation: wms-premium-loading-fade 1.8s ease-in-out infinite;
}

.wms-premium-route-loading__track {
  position: relative;
  width: 100%;
  max-width: 14rem;
  height: 0.28rem;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in oklab, var(--wms-brand-primary) 12%, hsl(var(--muted)));
}

.wms-premium-route-loading__track-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: 42%;
  border-radius: inherit;
  background: linear-gradient(
    90deg,
    color-mix(in oklab, var(--wms-brand-primary) 55%, transparent),
    var(--wms-brand-primary),
    color-mix(in oklab, var(--wms-brand-accent) 80%, var(--wms-brand-primary))
  );
  animation: wms-premium-loading-track 1.35s ease-in-out infinite;
}

.wms-premium-route-loading__track-shine {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent 0%,
    color-mix(in oklab, white 35%, transparent) 50%,
    transparent 100%
  );
  mix-blend-mode: soft-light;
  animation: wms-premium-loading-shine 1.8s linear infinite;
}

.wms-premium-route-loading__steps {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.35rem;
  width: 100%;
}

.wms-premium-route-loading__step {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.28rem;
  font-family: var(--wms-premium-font);
  font-size: 0.58rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: color-mix(in oklab, hsl(var(--muted-foreground)) 80%, transparent);
  opacity: 0.55;
  transition: opacity 0.25s ease, color 0.25s ease;
}

.wms-premium-route-loading__step i {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
  background: color-mix(in oklab, var(--wms-brand-primary) 25%, hsl(var(--muted)));
}

.wms-premium-route-loading__step--done {
  opacity: 0.85;
  color: color-mix(in oklab, var(--wms-brand-primary) 45%, hsl(var(--foreground)));
}

.wms-premium-route-loading__step--done i {
  background: var(--wms-brand-primary);
}

.wms-premium-route-loading__step--active {
  opacity: 1;
  color: var(--wms-brand-primary);
}

.wms-premium-route-loading__step--active i {
  background: var(--wms-brand-accent);
  box-shadow: 0 0 10px color-mix(in oklab, var(--wms-brand-accent) 55%, transparent);
  animation: wms-premium-loading-fade 1s ease-in-out infinite;
}

@keyframes wms-premium-loading-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes wms-premium-loading-spin-rev {
  to {
    transform: rotate(-360deg);
  }
}

@keyframes wms-premium-loading-pulse {
  0%,
  100% {
    transform: scale(0.82);
    opacity: 0.55;
  }
  50% {
    transform: scale(1);
    opacity: 1;
  }
}

@keyframes wms-premium-loading-fade {
  0%,
  100% {
    opacity: 0.62;
  }
  50% {
    opacity: 1;
  }
}

@keyframes wms-premium-loading-glow {
  0%,
  100% {
    opacity: 0.45;
    transform: scale(0.92);
  }
  50% {
    opacity: 0.9;
    transform: scale(1.05);
  }
}

@keyframes wms-premium-loading-track {
  0% {
    transform: translateX(-110%);
  }
  100% {
    transform: translateX(260%);
  }
}

@keyframes wms-premium-loading-shine {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(100%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .wms-premium-loading__ring,
  .wms-premium-loading__core,
  .wms-premium-loading__message,
  .wms-premium-route-loading__ring,
  .wms-premium-route-loading__core,
  .wms-premium-route-loading__message,
  .wms-premium-route-loading__glow,
  .wms-premium-route-loading__spark,
  .wms-premium-route-loading__pulse-dot,
  .wms-premium-route-loading__track-fill,
  .wms-premium-route-loading__track-shine,
  .wms-premium-route-loading__step--active i {
    animation: none;
  }
}

