@keyframes wms-ops-receipt-glitch-flip {
  0% {
    transform: translateY(var(--wms-flip-dy, 0px));
    filter: none;
    opacity: 1;
  }
  12% {
    transform: translateY(calc(var(--wms-flip-dy, 0px) * 0.82)) translateX(2px) skewX(-1.2deg);
    filter:
      brightness(1.2)
      contrast(1.25)
      drop-shadow(-2px 0 0 color-mix(in oklab, #22d3ee 70%, transparent))
      drop-shadow(2px 0 0 color-mix(in oklab, #f472b6 55%, transparent));
  }
  28% {
    transform: translateY(calc(var(--wms-flip-dy, 0px) * 0.58)) translateX(-2px) skewX(1deg);
    filter:
      brightness(1.1)
      contrast(1.35)
      drop-shadow(2px 0 0 color-mix(in oklab, #22d3ee 55%, transparent))
      drop-shadow(-1px 0 0 color-mix(in oklab, #a3e635 40%, transparent));
    clip-path: inset(8% 0 18% 0);
  }
  48% {
    transform: translateY(calc(var(--wms-flip-dy, 0px) * 0.28)) translateX(1px);
    filter: brightness(1.15) contrast(1.15);
    clip-path: inset(0 0 0 0);
  }
  72% {
    transform: translateY(calc(var(--wms-flip-dy, 0px) * 0.08));
    filter: brightness(1.05);
  }
  100% {
    transform: translateY(0);
    filter: none;
    clip-path: inset(0 0 0 0);
    opacity: 1;
  }
}

